/* Individual current-statute act/fault findings for special-law cards.
 * The quoted source snapshots bind each review to the manually reviewed
 * paragraph, not to a loose word match or a grade/penalty inference.
 * Historic applicability, case law and police powers remain separate.
 */
(()=>{'use strict';const D=window.BK_DATA,W=window.BK_STATUTES;if(!D?.crimes||!W)return;
const ROOT='https://www.riksdagen.se/sv/dokument-och-lagar/dokument/svensk-forfattningssamling/';
const laws={
 NSL:ROOT+'narkotikastrafflag-196864_sfs-1968-64/',
 VapenL:ROOT+'vapenlag-2026408_sfs-2026-408/',
 TBL:ROOT+'lag-1951649-om-straff-for-vissa-trafikbrott_sfs-1951-649/',
 KnivL:ROOT+'lag-1988254-om-forbud-betraffande-knivar-och_sfs-1988-254/',
 BidrBrL:ROOT+'bidragsbrottslag-2007612_sfs-2007-612/',
 SkBrL:ROOT+'skattebrottslag-197169_sfs-1971-69/',
 SmuglL:ROOT+'lag-20001225-om-straff-for-smuggling_sfs-2000-1225/',
 PTBL:ROOT+'lag-2014307-om-straff-for-penningtvattsbrott_sfs-2014-307/',
 LBE:ROOT+'lag-20101011-om-brandfarliga-och-explosiva_sfs-2010-1011/'
};
const rows=[];const add=(title,code,objective,subjective,refs)=>rows.push({title,code,objective,subjective,refs});
add('Narkotikabrott · innehav','NSL',
'Olovligt innehav av narkotika enligt 1 § första stycket 5. Innehav ska skiljas från enbart närvaro där narkotika finns och från bruk. Ämnets narkotikaklassning enligt 8 § och faktisk rådighet behöver utredas. Eget bruk är inte ett allmänt undantag från fullbordat innehav.',
'Uppsåt krävs till innehavet, olovligheten och de faktiska omständigheter som gör föremålet till narkotika. Uppsåt förutsätter inte kännedom om den juridiska brottsrubriceringen. Medveten kontakt med ett paket bevisar inte ensam uppsåt till ett narkotikainnehav.',['NSL 1 § första stycket 5','NSL 8 §','BrB 1:2']);
add('Ringa narkotikabrott · bruk','NSL',
'Olovligt bruk av narkotika enligt 1 § första stycket 5 och ringa grad enligt 2 §. Provresultat, intag och narkotikaklassning ska knytas till gärningen. Förstadieundantaget för bruk innebär inte att fullbordat olovligt bruk är straffritt.',
'Uppsåt krävs till det olovliga narkotikabruket och de relevanta ämnes-/intagsförhållandena. Ofrivilligt intag är inte automatiskt ett uppsåtligt bruk. Bestämmelsen om vårdslöshet med narkotika i 3 a § ersätter inte brukets uppsåtskrav.',['NSL 1 § första stycket 5','NSL 2 §','NSL 3 a §','BrB 1:2']);
add('Narkotikabrott · överlåtelse','NSL',
'Olovlig överlåtelse av narkotika till annan enligt 1 § första stycket 1. Det behöver inte vara en försäljning: en annan överlåtelse kan omfattas. En faktisk försäljning eller befattning med narkotika avsedd att säljas har ett särskilt straffskalealternativ i andra stycket.',
'Uppsåt krävs till överlåtelsen och de faktiska omständigheterna kring narkotikan. Skilj uppsåtlig överlåtelse från den särskilt straffbelagda grova oaktsamheten i 3 a §. Att lämna över något utan insikt om narkotikan uppfyller inte automatiskt uppsåtsbrottet.',['NSL 1 § första–andra styckena','NSL 3 a §','BrB 1:2']);
add('Narkotikabrott · framställning','NSL',
'Olovlig framställning av narkotika som är avsedd för missbruk enligt 1 § första stycket 2. Utred framställningsgärningen, narkotikaklassningen och missbruksanknytningen. Försäljningsavsedd narkotika omfattas därutöver av andra styckets särskilda straffskala.',
'Uppsåt ska omfatta den relevanta framställningsgärningen och faktiska omständigheter kring narkotikan och dess missbruksavsikt. För denna gärningsform finns ett separat grovt oaktsamhetsansvar i 3 a §; det är inte samma sak som uppsåtligt narkotikabrott.',['NSL 1 § första stycket 2','NSL 3 a §','BrB 1:2']);
add('Narkotikabrott · förvärv i överlåtelsesyfte','NSL',
'Olovligt förvärv av narkotika enligt 1 § första stycket 3 med det särskilda överlåtelsesyftet. Förvärv för eget bruk får inte utan vidare beskrivas som denna gärningsform; ett innehav kan i stället omfattas av punkt 5.',
'Uppsåt krävs till förvärvet och de relevanta narkotikaförhållandena, samt det uttryckliga syftet att överlåta narkotikan. Utred syftet särskilt. Att den som förvärvar skulle kunna överlåta varan senare räcker inte ensamt för att styrka detta subjektiva rekvisit.',['NSL 1 § första stycket 3 och 5','BrB 1:2']);
add('Narkotikabrott · transport/förvaring','NSL',
'Anskaffning, bearbetning, förpackning, transport, förvaring eller jämförlig befattning enligt 1 § första stycket 4 avser narkotika som inte är avsedd för eget bruk. Egetbruksbegränsningen gäller denna gärningsform; den gör inte ett samtidigt innehav enligt punkt 5 straffritt.',
'Uppsåt till befattningen och de relevanta narkotika- och användningsförhållandena krävs. Vårdslöshet med narkotika i 3 a § är en separat grov oaktsamhetsregel för angivna gärningar. Ren transportnärvaro är inte i sig bevis för uppsåtlig narkotikahantering.',['NSL 1 § första stycket 4–5','NSL 3 a §','BrB 1:2']);
add('Narkotikabrott · försäljning','NSL',
'En gärning enligt 1 § första stycket innebär att narkotika säljs eller att personen annars befattar sig med narkotika avsedd att säljas. Den särskilda andra-styckesskalan gäller alltså inte bara den som själv tar emot betalningen. Försäljningsanknytningen behöver visas.',
'Uppsåt krävs till de relevanta gärningsförhållandena, däribland narkotikans försäljningsanknytning. Uppsåt att själv tjäna pengar är inte ett generellt fristående krav i andra stycket. Skilj från särskild grov oaktsamhet enligt 3 a §.',['NSL 1 § andra stycket','NSL 3 a §','BrB 1:2']);
add('Narkotikabrott · främjande av handel','NSL',
'Olovligt utbjudande till försäljning, hantering av vederlag, kontaktförmedling eller annan sådan åtgärd enligt 1 § tredje stycket. Förfarandet ska vara ägnat att främja narkotikahandel. Gärningsformen kräver inte att personen själv har narkotika i besittning.',
'Uppsåt krävs till gärningen och relevanta faktiska omständigheter; ägnat att är ett objektivt lämplighetskrav och inte ett krav på att handeln faktiskt lyckas. Grov oaktsamhet behandlas separat i 3 a §. Social kontakt med säljare eller köpare räcker inte automatiskt.',['NSL 1 § tredje stycket','NSL 3 a §','BrB 1:2']);
add('Ringa narkotikabrott · innehav','NSL',
'Olovligt innehav enligt 1 § första stycket 5 som vid en helhetsbedömning av art, mängd och övriga omständigheter är ringa enligt 2 §. Ringa innehav är straffbelagt. Det får inte blandas ihop med brukets särskilda förstadieundantag.',
'Uppsåt krävs till innehavet och narkotikans relevanta faktiska förhållanden. Ringa grad ändrar inte detta skuldkrav. Enbart ett positivt prov eller att narkotika finns i ett gemensamt utrymme avgör inte i sig om personen uppsåtligen innehaft den.',['NSL 1 § första stycket 5','NSL 2 §','BrB 1:2']);
add('Grovt narkotikabrott','NSL',
'En gärning enligt 1 § ska föreligga. Vid grovhetsprövningen beaktas särskilt större omfattning eller yrkesmässighet, särskilt stor mängd och särskilt farlig eller hänsynslös art. Art och mängd är viktiga men ersätter inte en helhetsbedömning eller de bakomliggande gärningsrekvisiten.',
'Uppsåtskraven för den aktuella 1 §-gärningen kvarstår. Utred de faktiska omständigheter som bär grovhetsbedömningen och de särskilda syften som den valda gärningsformen kräver. Grov oaktsamhet är inte en generell skuldform för grovt narkotikabrott.',['NSL 1 §','NSL 3 § första stycket','BrB 1:2']);
add('Synnerligen grovt narkotikabrott','NSL',
'En narkotikagärning enligt 1 § med synnerligen grov grad enligt 3 § andra stycket. Särskilt beaktas organiserad storskalig handel, synnerligen stor mängd och synnerligen farlig eller hänsynslös art. Dessa grunder ska knytas till gärningen i en samlad bedömning.',
'Uppsåt krävs enligt den aktuella 1 §-gärningen och dess särskilda subjektiva rekvisit. Utred kännedom om faktiska mängd-, roll- och verksamhetsförhållanden. Synnerligen grov är domstolens rättsliga gradering och kan inte ersätta en självständig täckningsprövning.',['NSL 1 §','NSL 3 § andra stycket','BrB 1:2']);
add('Vapenbrott','VapenL',
'Innehav eller tillverkning av skjutvapen utan rätt, alternativt överlåtelse, yrkesmässig förmedling eller utlåning till någon utan rätt att inneha vapnet. Vapenklassning, faktisk rådighet, tillstånd och andra rättigheter ska prövas för den valda gärningsformen.',
'18 kap. 1 § första stycket kräver uttryckligen uppsåt till den relevanta gärningen och de faktiska omständigheterna bakom den otillåtna befattningen. Ett skjutvapen i närheten bevisar inte i sig uppsåtligt innehav. Oaktsamhetsalternativet finns särskilt i tredje stycket.',['VapenL 18:1','VapenL 1–2 kap.']);
add('Mindre allvarligt vapenbrott','VapenL',
'En grundgärning enligt 18 kap. 1 § första stycket föreligger men är mindre allvarlig med hänsyn till risken för brottslig eller annan skadlig användning och övriga omständigheter. Detta är en bedömning av gärningens grad och riskbild, inte ett automatiskt ringa-undantag.',
'Gärningen i mindre allvarlig grad är fortfarande uppsåtlig enligt första och andra styckena. Den ska skiljas från det egna oaktsamhetsalternativet i tredje stycket, även om straffskalorna sammanfaller. En låg risk för skadlig användning innebär inte att uppsåt saknas.',['VapenL 18:1 första–tredje styckena']);
add('Vapenbrott av oaktsamhet','VapenL',
'Någon av grundgärningarna i 18 kap. 1 § första stycket är aktuell: otillåtet innehav/tillverkning eller angiven överlåtelse, yrkesmässig förmedling eller utlåning. Föremålet ska vara ett skjutvapen som omfattas av lagen och rätten till befattningen ska saknas.',
'Tredje stycket straffbelägger uttryckligen oaktsamhet. Bedöm vad personen kunde och borde ha gjort för att upptäcka de otillåtna förhållandena. Detta alternativ är inte samma sak som uppsåtligt mindre allvarligt vapenbrott och leder inte automatiskt till grov grad.',['VapenL 18:1 första och tredje styckena']);
add('Grovt vapenbrott','VapenL',
'Uppsåtlig grundgärning enligt 18 kap. 1 § första stycket. Särskilt beaktas innehav på allmän/samlingsplats eller i fordon där, särskilt farligt vapen, flera vapen, brottslighetsanknuten innehavs-/tillverkningsmiljö och annars särskilt farlig gärning. Alternativen avser delvis olika gärningsformer.',
'Graderingen i 18 kap. 2 § hänvisar till det uppsåtliga första-styckesbrottet. Den vanliga oaktsamhetsvarianten kan inte automatiskt göras grov. Täck de faktiska förhållanden som bär gärningen och kvalifikationen; juridisk kännedom om ordet grovt krävs inte.',['VapenL 18:1–2']);
add('Synnerligen grovt vapenbrott','VapenL',
'Uppsåtlig grundgärning och synnerligen grov grad. Ett stort antal vapen eller flera särskilt farliga vapen ska särskilt beaktas. Lagens regel om kraftfulla eller särskilt farligt konstruerade/utformade enhandsvapen gäller farlighetsbedömningen; ingen enstaka faktor ersätter hela graderingen.',
'18 kap. 2 § andra stycket gäller ett brott enligt 1 § första stycket och förutsätter dess uppsåtskrav. Utred faktiska vapen-, mängd-, hanterings- och kunskapsförhållanden. Synnerligen grovt vapenbrott är inte ett särskilt grovt oaktsamhetsbrott.',['VapenL 18:1–2']);
add('Rattfylleri','TBL',
'Skilj alkoholgränsen, narkotika i blodet och klinisk påverkan vid förande av motordrivet fordon eller spårvagn. Ordinationsundantaget gäller narkotikaalternativet, inte all farlig medicinpåverkad körning. Undantaget för fordon avsett att föras av gående gäller första–andra styckena, inte det kliniska tredje stycket.',
'Uppsåt krävs enligt huvudregeln till körningen och de relevanta faktiska intags-/påverkansförhållandena. Det krävs inte att personen själv känner sin exakta alkoholhalt eller lagens promillegräns. Ordinerat intag och medvetenhet om körning/påverkan måste bedömas i rätt gärningsalternativ.',['TBL 4 §','BrB 1:2']);
add('Grovt rattfylleri','TBL',
'Grundbrott enligt något av 4 § första–tredje styckena föreligger. Vid grovhetsbedömningen beaktas särskilt minst 1,0 promille/0,50 mg/l, annars avsevärd påverkan eller påtaglig trafiksäkerhetsfara. Alkoholalternativets mätgräns får inte mekaniskt ersätta de andra alternativen.',
'Grundbrottets uppsåtskrav kvarstår. Utred personens faktiska intag, körning och påverkan samt de omständigheter som bär graden. Exakt uppfattad promillesiffra eller avsikt att köra farligt är inte generella särskilda skuldkrav för rubriceringen.',['TBL 4–4 a §§','BrB 1:2']);
add('Olovlig körning','TBL',
'Faktiskt förande av körkortspliktigt fordon utan behörighet, med de i 3 § fjärde stycket jämställda fordonskategorierna. Körning utan rätt ska skiljas från föreskriftsöverträdelse och tillåtande av annans körning enligt andra–tredje styckena.',
'Första stycket kräver uttryckligen uppsåt till obehörig körning. Att körkortsrätt faktiskt saknas räcker inte ensamt för att visa uppsåt. Andra och tredje styckenas separata oaktsamhetsansvar får inte göras till en allmän oaktsamhetsregel för den egna körningen i första stycket.',['TBL 3 §']);
add('Grov olovlig körning','TBL',
'Uppsåtlig obehörig körning enligt 3 § första stycket. Tidigare återkallat körkort, vanemässighet och andra grovhetsomständigheter ska prövas. Den grova graden är inte ett eget allmänt brott för varje överträdelse av en körkortsföreskrift.',
'Uppsåtskravet för obehörig körning kvarstår även vid grov grad. Utred vad personen visste om de förhållanden som gjorde körningen obehörig och de faktiska omständigheterna bakom graderingen. Upprepad körning ersätter inte bevisningen om uppsåt i den aktuella gärningen.',['TBL 3 § första och fjärde styckena']);
add('Brott mot knivlagen','KnivL',
'Skilj platsanknutet innehav enligt 1 § första stycket, under-21-innehav av springkniv/springstilett enligt tredje stycket och överlåtelse/saluhållande enligt 2 §. Vapenlagens företräde, befogat innehav för rätt alternativ och ringa-undantaget ska prövas. Saluhållandeförbudet i 2 § är inte begränsat till unga köpare.',
'4 § första stycket avser uppsåt. Oaktsamhet är separat straffbelagd i andra stycket med en annan straffskala. Täckning av faktiska föremåls-, plats- och hanteringsförhållanden ska skiljas från juridisk kunskap om vad som anses befogat.',['KnivL 1–4 §§']);
add('Grovt brott mot knivlagen','KnivL',
'Uppsåtligt grundbrott enligt 1 eller 2 § och grovhetsprövning enligt 4 § tredje stycket. Beakta särskilt angreppsrisk, särskilt farligt föremål, flera föremål eller annars särskilt farlig gärning. Lagen skiljer föremålets beskaffenhet från den konkreta gärningens riskbild.',
'Den grova graden hänvisar till första styckets uppsåtliga brott. Oaktsamhetsvarianten i andra stycket ska inte automatiskt ges grov grad. Utred relevanta faktiska omständigheter bakom föremålen, platsen och risken; enbart gärningspersonens juridiska etikett saknar avgörande betydelse.',['KnivL 1–4 §§']);
add('Bidragsbrott','BidrBrL',
'Oriktig uppgift eller utebliven anmälan av ändrade förhållanden som personen enligt lag eller förordning är skyldig att anmäla. Gärningen ska orsaka fara för felaktig utbetalning eller tillgodoräknande av en förmån eller ett stöd som omfattas av 1 §. Faktisk utbetalning är inte ett allmänt fullbordanskrav.',
'Uppsåt krävs till relevant oriktighet eller underlåtenhet och de faktiska förhållanden som skapar bidragsfaran. Skilj från det separata grova oaktsamhetsansvaret i 4 §. Mottaget bidrag eller en ändrad livssituation visar inte ensamt att en uppsåtlig feluppgift lämnats.',['BidrBrL 1–2 §§','BrB 1:2']);
add('Ringa bidragsbrott','BidrBrL',
'Grundrekvisiten i 2 § ska vara uppfyllda och gärningen därefter bedömas som ringa. Det krävs fortfarande oriktig uppgift eller lag-/förordningsgrundad ändringsanmälan och orsakad fara. Ringa uppsåtligt brott är straffbelagt, till skillnad från 4 § andra styckets ansvarsfrihet för mindre allvarlig oaktsam gärning.',
'Uppsåtskravet följer med grundgärningen i 2 §. En ringabedömning gör inte vanlig oaktsamhet tillräcklig. Utred personens kännedom om faktiska förändringar, uppgiftslämnande och risken för felaktig förmån; den juridiska gradbeteckningen behöver inte vara känd.',['BidrBrL 2 och 4 §§','BrB 1:2']);
add('Grovt bidragsbrott','BidrBrL',
'En uppsåtlig gärning enligt 2 § som bedöms som grov. Betydande belopp, falska handlingar och systematisk brottslighet eller större omfattning ska särskilt beaktas. Faktisk slutlig förlust är inte ett nytt allmänt rekvisit som ersätter grundbrottets fara för felaktig bidragshantering.',
'Uppsåt ska prövas för grundgärningen och de relevanta faktiska förhållandena bakom dess kvalifikation. Den grova graden är inte ett alternativt oaktsamhetsbrott. Uppsåt till varje faktisk omständighet ska hållas isär från domstolens rättsliga värdering att förfarandet är grovt.',['BidrBrL 2–3 §§','BrB 1:2']);
add('Vårdslöst bidragsbrott','BidrBrL',
'En gärning av den art som 2 § anger, alltså även relevant utebliven ändringsanmälan, med föreskriven bidragsfara. Om beloppet, risken för slutlig ekonomisk skada och övriga omständigheter gör gärningen mindre allvarlig följer ansvarsfrihet enligt 4 § andra stycket.',
'Grov oaktsamhet krävs enligt 4 §; vanlig oaktsamhet räcker inte. Bedöm vilka risktecken personen kunde och borde ha uppmärksammat och hur klandervärt agerandet var. Skilj denna skuldprövning från den efterföljande frågan om gärningen är mindre allvarlig.',['BidrBrL 1–2 och 4 §§']);
add('Skattebrott','SkBrL',
'Oriktig myndighetsuppgift eller utebliven deklaration, kontrolluppgift eller annan föreskriven myndighetsuppgift som ger upphov till föreskriven skattefara. Lagens tillämpningsområde och undantag i 1 § ska beaktas. Skatt behöver inte faktiskt ha undandragits för att farebrottet ska vara fullbordat.',
'2 § kräver uttryckligen uppsåt till relevant uppgift/underlåtenhet och skattefarans faktiska omständigheter. Ett fel i deklarationen bevisar inte uppsåt. Det grova oaktsamhetsansvaret i 5 § gäller oriktigt uppgiftslämnande och kan inte automatiskt användas för varje utebliven deklaration.',['SkBrL 1–2 och 5 §§']);
add('Skatteförseelse','SkBrL',
'Ett skattebrott enligt 2 § bedöms som ringa enligt 3 §. Rekvisiten för oriktig eller utebliven föreskriven uppgift och den orsakade skattefaran kvarstår. Den särskilda åtalsregeln i 13 § är en processuell fråga och betyder inte att en ringa gärning i sig är straffri.',
'Grundgärningen är uppsåtlig även i ringa grad. Bedöm täckning av uppgiftens faktiska oriktighet, skyldighetsförhållanden och skattefaran. Brottsgraden får inte användas för att kringgå uppsåtskravet eller för att blanda samman skatteförseelse och vårdslös skatteuppgift.',['SkBrL 2–3 och 13 §§']);
add('Grovt skattebrott','SkBrL',
'Grundgärning enligt 2 § med grov grad. Mycket betydande belopp, falska handlingar eller vilseledande bokföring, systematik/större omfattning och synnerligen farlig art är särskilda grovhetsgrunder. De är inte en kumulativ lista där alla måste vara uppfyllda.',
'Uppsåt krävs enligt grundbestämmelsen och ska prövas mot den relevanta uppgifts- eller underlåtenhetsgärningen och skattefaran. Faktaunderlaget för grovhetsgrunderna ska också hanteras i täckningsprövningen. Att en skatteskuld är stor visar inte ensamt uppsåtligt grovt skattebrott.',['SkBrL 2 och 4 §§']);
add('Vårdslös skatteuppgift','SkBrL',
'Oriktig uppgift lämnas till myndighet och ger upphov till den skattefara som 5 § anger. Bestämmelsen gäller inte generellt varje underlåten deklaration. Gärning av mindre allvarlig art med hänsyn till skattebelopp och övriga omständigheter är undantagen.',
'Grov oaktsamhet krävs till det relevanta uppgiftslämnandet och de faktiska omständigheterna kring skattefaran. En felräkning eller ett faktiskt skattefel är inte i sig bevis för grov oaktsamhet. Uppsåtlig gärning prövas i stället enligt de tillämpliga uppsåtsbestämmelserna.',['SkBrL 2 och 5 §§']);
add('Skatteavdragsbrott','SkBrL',
'Underlåtenhet att fullgöra en skyldighet att göra skatteavdrag enligt skatteförfarandelagen. Identifiera den faktiska avdragsskyldigheten, den ansvariga personen och det uteblivna avdraget. Ringa fall medför inte ansvar enligt 6 §. Obetald skatt ensam avgör inte om just detta brott är uppfyllt.',
'6 § omfattar både uppsåt och grov oaktsamhet, inte generell vanlig oaktsamhet. Skuldprövningen ska avse det uteblivna fullgörandet och relevanta faktiska skyldighetsförhållanden. Företagets betalningsproblem eller personens befattning ersätter inte denna individuella prövning.',['SkBrL 6 §','Skatteförfarandelagen (2011:1244)']);
add('Skatteredovisningsbrott','SkBrL',
'Skilj oriktig myndighetsuppgift, uppgift till avdrags-/kontrolluppgiftsskyldig och underlåten föreskriven uppgift. Underlåtenhetsalternativet förutsätter uppgift utan föreläggande eller uppmaning och omfattar inte egen inkomstdeklaration. Regeln är subsidiär till 2 § och undantar ringa fall.',
'Uppsåt krävs för det valda alternativet i 7 §. För oaktsamhetsfrågor ska den snävare hänvisningen i 8 § läsas särskilt; den omfattar inte automatiskt alla tre uppsåtliga gärningsvägar. En utebliven handling måste knytas till vad personen faktiskt insåg och underlät.',['SkBrL 2 och 7–8 §§']);
add('Vårdslös skatteredovisning','SkBrL',
'Gärning enligt 7 § första stycket 2 eller andra stycket. Hänvisningen omfattar alltså inte generellt det aktiva oriktiga myndighetsuppgiftslämnandet i första stycket 1. Underlåtenhetens egna begränsningar och ringa-undantaget ska fortfarande prövas.',
'8 § kräver grov oaktsamhet. Vanlig oaktsamhet räcker inte och kan inte heller utvidga vilka gärningar hänvisningen omfattar. Bedöm personens möjlighet och anledning att upptäcka risken i den aktuella uppgifts- eller underlåtenhetssituationen.',['SkBrL 7 § första stycket 2 och andra stycket','SkBrL 8 §']);
add('Försvårande av skattekontroll','SkBrL',
'Åsidosättande av bokföringsskyldighet eller föreskriven skyldighet att föra och bevara räkenskaper ger fara för att myndighetens kontroll vid beräkning eller uppbörd av skatt/avgift allvarligt försvåras. Det räcker inte att kontrollen blir obekväm. Ringa fall är undantagna.',
'10 § omfattar uppsåt eller grov oaktsamhet i förhållande till relevanta skyldighets-, åsidosättande- och faroförhållanden. Vanlig oaktsamhet räcker inte. Utred vem som faktiskt bar skyldigheten och dennes individuella agerande; bokföringsbrist är inte en automatisk personlig skuldpresumtion.',['SkBrL 10 §']);
add('Grovt försvårande av skattekontroll','SkBrL',
'Samma materiella kontrollförsvåranderekvisit som i 10 § grundfall, med separat bedömning att brottet är grovt. Bestämmelsen anger inte en fristående uppräkning av grovhetsgrunder som kan ersätta grundrekvisiten. Allvarlig försvårandefara ska finnas även i denna grad.',
'Alternativen uppsåt och grov oaktsamhet gäller även vid grov grad. Den rättsliga graderingen innebär inte att skuldformen automatiskt ska ändras till uppsåt eller att varje stor bokföringsbrist är grovt brott. Täckning och grad behöver var sin motiverad prövning.',['SkBrL 10 §']);
add('Smuggling','SmuglL',
'Särskilt föreskrivet införsel-/utförselförbud eller villkor överträds genom någon av gärningsformerna i 3 §. Skilj utebliven anmälan, oriktig/utebliven tulluppgift, utförsel, förfogande under tullbehandling och tillståndsfallen. Varje alternativ har egna gräns-, fare- eller fullföljandekrav.',
'3 § föreskriver uppsåt. Det ska täcka den relevanta hanteringen, uppgifts-/underlåtenhetsgärningen och de faktiska omständigheterna bakom förbudet eller villkoret. Grov oaktsamhet bedöms enligt 7 §; en utebliven tullanmälan bevisar inte automatiskt uppsåt.',['SmuglL 2–3 och 7 §§']);
add('Ringa smuggling','SmuglL',
'Gärningsrekvisiten i 3 § ska vara uppfyllda och brottet bedömas som ringa enligt 4 §. Det är inte samma sak som ett ringa oaktsamt 7 §-fall, där ansvar är uteslutet. Penningböter enligt 4 § ger inte i sig något positivt besked om fängelsebaserade tvångsmedel.',
'Ringa grad behåller 3 §-gärningens uppsåtskrav. Skilj den objektiva graderingen från subjektiv täckning av den konkreta införseln, utförseln eller förfogandet. Vanlig oaktsamhet är inte en generell alternativ skuldform för ringa smuggling.',['SmuglL 3–4 och 7 §§']);
add('Grov smuggling','SmuglL',
'En gärning enligt 3 § och separat grovhetsbedömning enligt 5 §. Systematik eller större omfattning, särskilt farlig art och allvarlig kränkning av betydande samhällsintresse ska särskilt beaktas. Grundgärningens förbud/villkor och alternativa fullbordanskrav kvarstår.',
'Uppsåt till grundgärningen krävs även vid grov grad. Utred de faktiska förhållandena som bär kvalifikationen och personens relevanta kännedom om dem. Att en införsel objektivt är omfattande ersätter inte prövningen av uppsåt.',['SmuglL 3 och 5 §§']);
add('Narkotikasmuggling','SmuglL',
'En gärning enligt 3 § gäller narkotika enligt 2 § och NSL 8 §. Försäljningsavsikt är inte ett generellt krav för grundfallet. Förbud/villkor, faktisk varuklassning och det åberopade smugglingsalternativet behöver identifieras; vanligt inhemskt innehav är inte automatiskt smuggling.',
'Uppsåt krävs enligt 3 § till relevant gräns-/tullgärning och narkotikaförhållandena. Försäljningssyfte är inte ett extra skuldkrav för varje grundfall. Grov oaktsamhet kan i tillämpliga fall bedömas separat enligt 7 §.',['SmuglL 2–3 och 6–7 §§']);
add('Narkotikasmuggling – avsedd att säljas','SmuglL',
'Samma grundgärning enligt 3 och 6 §§, med tilläggsförhållandet att narkotikan är avsedd att säljas. 6 § andra stycket ger ett särskilt straffskalealternativ, inte ett nytt självständigt gränsbrott. Narkotikan behöver inte redan ha sålts när smugglingsgärningen fullbordas.',
'Uppsåt ska täcka grundgärningen och den relevanta försäljningsanknytningen. Det är inte nödvändigtvis gärningspersonen själv som ska sälja narkotikan. Ett litet egetbruksparti ska inte ges denna skala enbart för att narkotika i allmänhet kan säljas vidare.',['SmuglL 3 och 6 §§']);
add('Ringa narkotikasmuggling','SmuglL',
'En narkotikasmugglingsgärning enligt 3 och 6 § första stycket som efter samlad bedömning är ringa. Varuslag och gärningsalternativ kvarstår som krav. Ringa narkotikasmuggling har inte samma straffregel som ringa vanlig smuggling eller ringa explosivvarusmuggling.',
'Uppsåtskraven i smugglingsgärningen kvarstår vid ringa grad. Personen behöver inte förstå den juridiska graderingen, men relevant faktisk narkotika- och gränshantering ska täckas. Ringa uppsåtsbrott och ringa oaktsam gärning enligt 7 § har olika ansvarsregler.',['SmuglL 3 och 6–7 §§']);
add('Grov narkotikasmuggling','SmuglL',
'Narkotikasmuggling med grov grad enligt 6 §. Särskilt stor mängd, större omfattning eller yrkesmässighet samt särskilt farlig eller hänsynslös verksamhet/gärning ska beaktas. Grundgärningen enligt 3 § och narkotikaklassningen ska vara uppfyllda innan graden bedöms.',
'Uppsåt krävs till den aktuella smugglingsgärningen och relevanta faktiska narkotikaförhållanden. Bedöm personens kännedom om roll, mängd och verksamhet där dessa bär kvalifikationen. Grov oaktsamhet utgör inte ett allmänt alternativ för grov narkotikasmuggling.',['SmuglL 2–3 och 6 §§']);
add('Synnerligen grov narkotikasmuggling','SmuglL',
'Narkotikasmuggling med synnerligen grov grad. Organiserad verksamhet för storskalig narkotikahandel, synnerligen stor mängd och synnerligen farlig eller hänsynslös art ska särskilt beaktas. Helhetsbedömningen ska avse den konkreta gärningen, inte enbart preparatnamn eller tabellmängd.',
'Uppsåtskraven för 3 §-gärningen gäller även denna grad. De faktiska kvalifikationsförhållandena ska hanteras i täckningsprövningen. Straffskalan eller omgivningens brottslighet kan inte ensam visa vad den enskilde uppfattade eller deltog i.',['SmuglL 3 och 6 §§']);
add('Vapensmuggling','SmuglL',
'En gärning enligt 3 § gäller vapen enligt den särskilda definitionen i 2 §, som hänvisar till vapenlagen. Detta är en annan gärningsfråga än endast inhemskt olovligt innehav. Identifiera gräns-/tullalternativet, förbud/villkor och vilket föremål som omfattas.',
'Uppsåt krävs till smugglingsgärningen och föremålets relevanta faktiska vapenegenskaper. Den separata oaktsamhetsregeln i 7 § ska hållas isär från vapensmuggling. Att någon medför en väska visar inte ensamt uppsåt till de vapen som eventuellt finns där.',['SmuglL 2–3 och 6 a–7 §§']);
add('Ringa vapensmuggling','SmuglL',
'Grundrekvisiten för vapensmuggling ska föreligga och gärningen bedömas som ringa enligt 6 a § andra stycket. Ringa grad är inte ett undantag från vapendefinitionen eller gräns-/tullgärningen. Den har bötes-/fängelseskala och ska inte sammanblandas med ringa explosivvarusmuggling.',
'Grundgärningen är uppsåtlig även om den bedöms ringa. Täckning av relevant förfarande och vapenförhållanden ska visas. Ett oavsiktligt åsidosättande prövas i stället mot den särskilda oaktsamhetsregeln, med dess egna ringa-undantag.',['SmuglL 3 och 6 a–7 §§']);
add('Grov vapensmuggling','SmuglL',
'Uppfylld vapensmuggling och grovhetsprövning enligt 6 a §. Särskilt farligt vapen, flera vapen, större omfattning/yrkesmässighet och särskilt farlig art är särskilt angivna faktorer. Platsrekvisiten för inhemskt grovt vapenbrott är inte automatiskt samma kvalifikationslista här.',
'Uppsåt ska omfatta smugglingsgärningen och relevanta faktiska vapenförhållanden; kvalifikationens faktaunderlag ska utredas särskilt. Grov grad kan inte grundas bara på att personen borde ha förstått att ett vapen fanns i transporten.',['SmuglL 3 och 6 a §§']);
add('Synnerligen grov vapensmuggling','SmuglL',
'Grundrekvisiten i 3 och 6 a §§ samt synnerligen grov grad. Ett stort antal vapen eller flera särskilt farliga vapen ska särskilt beaktas. Den särskilda regeln för kraftfulla eller särskilt farligt utformade enhandsvapen är relevant för farligheten men ersätter inte övrig helhetsprövning.',
'Även denna grad förutsätter uppsåtlig smugglingsgärning. Personens faktiska kännedom om föremål, hantering och kvalifikationsförhållanden ska utredas. En objektiv vapenteknisk klassning är inte i sig bevis för uppsåt till hela förfarandet.',['SmuglL 3 och 6 a §§']);
add('Smuggling av explosiv vara','SmuglL',
'En gärning enligt 3 § gäller explosiva varor enligt hänvisningen i 2 § till LBE 4 §. Förbud/villkor och rätt smugglingsalternativ ska fastställas. Varuklassning som explosiv är inte samma sak som att varje innehav eller transport utgör smuggling.',
'Uppsåt krävs till den relevanta smugglingsgärningen och faktiska explosivvaruförhållanden. Separat grov oaktsamhet enligt 7 § kan inte utan vidare beskrivas som uppsåtlig explosivvarusmuggling. Kännedom om juridisk SFS-beteckning är däremot inte ett fristående krav.',['SmuglL 2–3 och 6 b–7 §§','LBE 4 §']);
add('Ringa smuggling av explosiv vara','SmuglL',
'Explosivvarusmuggling enligt 3 och 6 b §§ bedöms som ringa efter en särskild helhetsvärdering. Straffet är penningböter enligt 6 b § andra stycket; det är inte samma bötes-/fängelseregel som för ringa vapensmuggling.',
'Uppsåt till grundgärningen och relevanta explosivvaruförhållanden kvarstår. Ringa uppsåtlig smuggling är straffbelagd; ringa oaktsam införsel/utförsel enligt 7 § är däremot undantagen. Graden får inte avgöra skuldformen utan särskild prövning.',['SmuglL 3 och 6 b–7 §§']);
add('Grov smuggling av explosiv vara','SmuglL',
'Grundgärningen och explosivvaruklassningen ska föreligga. Vid grovhetsprövningen beaktas effekt/konstruktion/utformning, flera varor eller stor mängd, större omfattning/yrkesmässighet samt särskilt farlig art. Denna lista ska läsas i 6 b §, inte kopieras okritiskt från LBE:s inhemska tillståndsbrott.',
'Uppsåtskraven i 3 § gäller även grov explosivvarusmuggling. Utred relevanta faktiska uppgifter om föremål, mängd och verksamhet. En kraftig explosiv vara kan vara betydelsefull för graden men visar inte ensam den enskildes uppsåt till smugglingsförfarandet.',['SmuglL 3 och 6 b §§']);
add('Synnerligen grov smuggling av explosiv vara','SmuglL',
'Explosivvarusmuggling med synnerligen grov grad enligt 6 b §. Särskilt beaktas stort antal eller särskilt stor mängd, flera särskilt farliga varor eller stor mängd av särskilt farlig vara. Grunderna är alternativ inom helhetsbedömningen, inte en obligatorisk kumulativ lista.',
'Grundgärningen är uppsåtlig och relevanta faktiska kvalifikationsförhållanden ska prövas i täckningen. Att varan har hög sprängverkan är en objektiv uppgift; det ersätter inte bevisning om vad personen gjorde och insåg kring gräns-/tullförfarandet.',['SmuglL 3 och 6 b §§']);
add('Olovlig införsel eller utförsel','SmuglL',
'Gärning enligt de i 7 § angivna smugglingsbestämmelserna eller dess särskilda utförsel-/tillståndsalternativ. Alternativen har egna farekrav där lagen anger dem. Ringa gärning är undantagen. Alla ofullständiga tulluppgifter omfattas inte utan koppling till de angivna förbuden eller villkoren.',
'Grov oaktsamhet är uttryckligt krav enligt 7 §. Vanlig oaktsamhet räcker inte. Bedöm vilken risk personen kunde och borde ha upptäckt och hur allvarlig försummelsen var; uppsåtlig gärning hör till motsvarande uppsåtsbestämmelse.',['SmuglL 3 och 6–7 §§']);
add('Tullbrott','SmuglL',
'Angiven anmälnings-, uppgifts-, förfogande- eller villkorsgärning skapar föreskriven fara för undandragen tull/skatt/avgift eller felaktigt tillgodoräknande/återbetalning. 8 § är begränsad till sådana belopp som Tullverket ska besluta. Särskild regel finns för centraliserad klarering i annat EU-land.',
'8 § kräver uppsåt till relevant gärningsförfarande och skatte-/avgiftsfarans faktiska omständigheter. Ett felaktigt deklarerat belopp avgör inte ensamt skuldfrågan. Grov oaktsamhet prövas enligt 11 § och får inte användas som en obestämd alternativ skuldform för tullbrott.',['SmuglL 8 och 11 §§']);
add('Ringa tullbrott','SmuglL',
'En gärning uppfyller 8 § och bedöms som ringa enligt 9 §. Skatte-/avgiftsfaran och Tullverkets beslutskoppling kvarstår som grundkrav. Straffet är penningböter; det skiljer sig från ringa oaktsam tullredovisning, som enligt 11 § är undantagen från ansvar.',
'Uppsåtskravet i 8 § följer med till ringa grad. Täck relevanta uppgifts-/underlåtenhetsförhållanden och den orsakade tullfaran. Den lindriga graden innebär inte att även ett rent misstag utan uppsåt är ringa tullbrott.',['SmuglL 8–9 och 11 §§']);
add('Grovt tullbrott','SmuglL',
'Grundrekvisiten i 8 § och grovhetsbedömning enligt 10 §. Mycket betydande belopp, falska handlingar/vilseledande bokföring, systematik/större omfattning och särskilt farlig art ska beaktas. Faktisk slutlig förlust är inte ett nytt allmänt krav som ersätter tullfaran.',
'Uppsåt krävs enligt 8 § till gärningen och relevanta faktiska faroförhållanden. Hantera de faktiska kvalifikationsomständigheterna i täckningsprövningen. Stor beloppsavvikelse är relevant utredning men utgör inte ensam bevis för uppsåt.',['SmuglL 8 och 10 §§']);
add('Vårdslös tullredovisning','SmuglL',
'En gärning enligt 8 § med dess föreskrivna tull-/skattefara och begränsning till Tullverkets beslutsområde. Ringa fall är uttryckligen undantagna i 11 §. En allmän bokföringsbrist utan koppling till ett 8 §-alternativ är inte automatiskt vårdslös tullredovisning.',
'11 § kräver grov oaktsamhet, inte enbart vanlig oaktsamhet. Bedöm personens konkreta möjlighet och anledning att upptäcka risken för felaktig tullhantering. Skilj denna individuella skuldprövning från bedömningen om gärningen är ringa och därmed ansvarsfri.',['SmuglL 8 och 11 §§']);
add('Olovlig befattning med smuggelgods','SmuglL',
'En uppräknad hantering, överlåtelse eller panträttsåtgärd avser vara som varit föremål för brott enligt 3–11 §§. Ringa-undantag och den uttryckliga subsidiariteten till vissa narkotika-, vapen- och explosivvarubrott ska beaktas. Tillåten efterföljande varuhantering kan inte bedömas bara utifrån varans utländska ursprung.',
'Första stycket kräver uppsåt. Andra stycket har en separat bötesvariant när personen inte inser men har skälig anledning att anta det brottsliga ursprunget. Dessa alternativ har olika skuldkrav och får inte ges samma straffskala eller automatiskt samma grovhetsbedömning.',['SmuglL 12 §']);
add('Grov olovlig befattning med smuggelgods','SmuglL',
'Grundgärning enligt 12 § första stycket, med separat grovhetsbedömning enligt 13 §. Systematik/större omfattning, anknytning till mycket betydande undandragna eller felaktigt återbetalda belopp och särskilt farlig art är särskilda faktorer. Subsidiaritets- och ringa-reglerna i grundbestämmelsen ska beaktas.',
'13 § hänvisar uttryckligen till det uppsåtliga första stycket i 12 §. Den skälig-anledning-att-anta-baserade bötesvarianten i andra stycket ska därför inte automatiskt göras grov. Utred relevant uppsåt och faktaunderlag bakom kvalifikationen.',['SmuglL 12–13 §§']);
add('Penningtvättsbrott','PTBL',
'Skilj 3 §-åtgärder med döljande-/tillgodogörandesyfte från 4 §-åtgärder som otillbörligen främjar omsättning utan det syftet. Egendomen ska härröra från brott eller brottslig verksamhet med den i 2 § angivna brottsanknytningen. Alternativen är inte kumulativa krav på samma gärning.',
'Uppsåt krävs till relevant befattning och de faktiska förhållandena kring brottsursprung och åtgärd. I 3 § ska åtgärdens särskilda syfte utredas; i 4 § krävs inte samma syfte. Oaktsamhet om ursprunget har en separat regel i 6 § och ska inte göras till normalbrottets allmänna skuldform.',['PTBL 2–4 och 6 §§','BrB 1:2']);
add('Grovt penningtvättsbrott','PTBL',
'En 3 eller 4 §-gärning föreligger och bedöms som grov enligt 5 §. Betydande värden, systematik/större omfattning och särskilt farlig art ska särskilt beaktas. De skilda grundalternativens syftes- respektive otillbörlighetskonstruktion kvarstår.',
'Uppsåtsprövningen ska göras mot det valda grundalternativets faktiska rekvisit, även vid grov grad. Det krävs inte att personen själv använder ordet penningtvätt eller grovt. Utred kännedom om relevanta åtgärds-, ursprungs- och kvalifikationsförhållanden.',['PTBL 2–5 §§','BrB 1:2']);
add('Penningtvättsförseelse','PTBL',
'6 § omfattar dels ringa fall av 3 eller 4 §-brott, dels den särskilda ursprungsrelaterade skuldvarianten i andra stycket. Den valda grundgärningens övriga krav måste fortfarande vara uppfyllda; varje misstänkt ekonomisk transaktion är inte automatiskt detta brott.',
'Skilj uppsåtlig ringa gärning från fallet där personen inte insåg men hade skälig anledning att anta egendomens brottsliga ursprung. Den senare regeln rör just ursprungsförhållandet och upphäver inte alla andra krav i den relevanta grundbestämmelsen.',['PTBL 3–4 och 6 §§']);
add('Näringspenningtvätt','PTBL',
'Medverkan i näringsverksamhet, vanemässig verksamhet eller annan större omfattning till en åtgärd som skäligen kan antas vara vidtagen i sådant syfte som 3 § anger. Konstruktionen ska inte ersättas av ett krav att samtliga objektiva rekvisit för vanligt penningtvättsbrott redan är bevisade.',
'Uppsåt ska prövas till medverkan och de faktiska verksamhets- och riskomständigheterna. Skäligen kan antas beskriver här bedömningen av åtgärdens syfte, inte en allmän skuldform som gör varje oaktsam bankkontakt straffbar. Bedömningen behöver konkret faktaunderlag.',['PTBL 3 och 7 §§','BrB 1:2']);
add('Grov näringspenningtvätt','PTBL',
'Grundrekvisiten i 7 § första stycket ska vara uppfyllda och brottet bedömas som grovt enligt andra stycket. Verksamhetsanknytningen och den särskilda åtgärds-/syfteskonstruktionen kvarstår. Paragrafen innehåller inte en egen uttömmande lista med obligatoriska grovhetsfaktorer.',
'Uppsåt till relevant medverkan och faktiska verksamhets-/riskförhållanden ska prövas även vid grov grad. Utred också de omständigheter som bär graderingen. Ett stort mottaget belopp är varken en automatisk uppsåtspresumtion eller ensam en fullständig grovhetsprövning.',['PTBL 3 och 7 §§','BrB 1:2']);
add('Ringa näringspenningtvätt','PTBL',
'7 § tredje stycket innehåller två vägar: ringa näringspenningtvätt och medverkan utanför första styckets verksamhetsram till en åtgärd med den angivna syftesindikationen. För den senare vägen är näringsverksamhet alltså inte ett obligatoriskt rekvisit.',
'Uppsåt till relevant medverkan och de faktiska riskförhållandena ska prövas. Den särskilda formuleringen skäligen kan antas avser åtgärden och dess syfte och får inte förväxlas med 6 §-regelns särskilda oaktsamhet om brottsursprung. Två lagvägar får inte bli ett enda kumulativt rekvisitpaket.',['PTBL 3 och 7 §§','BrB 1:2']);
add('Brott mot tillståndsplikten för brandfarliga varor','LBE',
'Yrkesmässig hantering eller hantering i större mängd av brandfarliga varor omfattas av 16 § första stycket, om tillämpligt undantag inte finns. Identifiera faktisk hantering, varuslag och tillståndsplikt. En brandfarlig vara i hemmet betyder inte i sig att varje hantering är tillståndspliktig.',
'29 § andra stycket 1 omfattar uppsåt eller grov oaktsamhet. Vanlig oaktsamhet har en separat bötesregel i första stycket och ska inte tilldelas andra styckets fängelseskala. Utred personens faktiska roll, kännedom och handlingsmöjligheter.',['LBE 4, 16 och 29–30 §§']);
add('Brott mot tillståndsplikten för explosiva varor','LBE',
'Tillståndspliktig hantering, överföring, import eller export av explosiva varor enligt 16 § första stycket utan tillämpligt undantag. Tillståndsregeln skiljer sig från den för brandfarliga varor. Varudefinition och de särskilda ansvarsfrihets-/subsidiaritetsreglerna i 30 § ska beaktas.',
'29 § andra stycket 2 omfattar uppsåt eller grov oaktsamhet. Vanlig oaktsamhet prövas enligt första styckets bötesregel. Utred faktisk befattning och personens skuld; egenskapen explosiv vara eller avsaknad av tillstånd visar inte ensam uppsåt eller grov oaktsamhet.',['LBE 4, 16 och 29–30 §§']);
add('Grovt brott mot tillståndsplikten för explosiva varor','LBE',
'Uppsåtligt tillståndsbrott enligt 16 § första stycket avseende explosiva varor. Vid grovhetsprövningen beaktas särskilt varans farlighet, flera varor/stor mängd, riskmiljö vid hantering eller överföring och särskilt farlig art. Import/exportsituationer ska även bedömas mot smugglingsföreträdet i 30 §.',
'29 a § kräver uttryckligen uppsåt för grov grad. Grov oaktsamhet enligt 29 § andra stycket räcker alltså inte automatiskt. Utred både relevant tillståndsöverträdelse och faktiska omständigheter som bär kvalifikationen; straffskalan bevisar inte skuldformen.',['LBE 16 och 29–30 §§']);
add('Synnerligen grovt brott mot tillståndsplikten för explosiva varor','LBE',
'Uppsåtligt tillståndsbrott avseende explosiva varor med synnerligen grov grad enligt 29 a §. Stort antal/särskilt stor mängd eller flera särskilt farliga varor/stor mängd av sådan vara ska särskilt beaktas. Alternativen ska värderas inom en helhet, inte krävas samtidigt.',
'Uppsåtskravet för 29 a § kvarstår vid synnerligen grov grad. Täckning av relevanta faktiska varu-, hanterings- och kvalifikationsförhållanden behöver utredas. Farligt material och dålig tillståndskontroll innebär inte utan vidare det uppsåt som den grova bestämmelsen kräver.',['LBE 16 och 29 a–30 §§']);
const pins={"Narkotikabrott · innehav":{"ref":"NSL 1 §","text":"1 § Den som olovligen 1. överlåter narkotika, 2. framställer narkotika som är avsedd för missbruk, 3. förvärvar narkotika i överlåtelsesyfte, 4. anskaffar, bearbetar, förpackar, transporterar, förvarar eller tar annan sådan befattning med narkotika som inte är avsedd för eget bruk, eller 5. innehar, brukar eller tar annan befattning med narkotika döms för narkotikabrott till fängelse i högst tre år. Om en gärning som avses i första stycket innebär att gärningsmannen säljer narkotika eller annars befattar sig med narkotika som är avsedd att säljas, döms i stället till fängelse i lägst sex månader och högst tre år. För narkotikabrott döms även den som olovligen bjuder ut narkotika till försäljning, förvarar eller befordrar vederlag för narkotika, förmedlar kontakter mellan säljare och köpare eller företar någon annan sådan åtgärd, om förfarandet är ägnat att främja narkotikahandel. Straffet är i ett sådant fall fängelse i lägst sex månader och högst tre år. Bestämmelser om straff för olovlig införsel och utförsel av narkotika och olovlig befattning i vissa fall med narkotika finns i lagen (2000:1225) om straff för smuggling. Lag (2023:258)."},"Ringa narkotikabrott · bruk":{"ref":"NSL 2 §","text":"2 § Är brott som avses i 1 § första stycket med hänsyn till arten och mängden narkotika samt övriga omständigheter att anse som ringa, döms för ringa narkotikabrott till böter eller fängelse i högst sex månader. Lag (2016:488)."},"Narkotikabrott · överlåtelse":{"ref":"NSL 1 § 1 st. 1","text":"1 § Den som olovligen 1. överlåter narkotika, 2. framställer narkotika som är avsedd för missbruk, 3. förvärvar narkotika i överlåtelsesyfte, 4. anskaffar, bearbetar, förpackar, transporterar, förvarar eller tar annan sådan befattning med narkotika som inte är avsedd för eget bruk, eller 5. innehar, brukar eller tar annan befattning med narkotika döms för narkotikabrott till fängelse i högst tre år. Om en gärning som avses i första stycket innebär att gärningsmannen säljer narkotika eller annars befattar sig med narkotika som är avsedd att säljas, döms i stället till fängelse i lägst sex månader och högst tre år. För narkotikabrott döms även den som olovligen bjuder ut narkotika till försäljning, förvarar eller befordrar vederlag för narkotika, förmedlar kontakter mellan säljare och köpare eller företar någon annan sådan åtgärd, om förfarandet är ägnat att främja narkotikahandel. Straffet är i ett sådant fall fängelse i lägst sex månader och högst tre år. Bestämmelser om straff för olovlig införsel och utförsel av narkotika och olovlig befattning i vissa fall med narkotika finns i lagen (2000:1225) om straff för smuggling. Lag (2023:258)."},"Narkotikabrott · framställning":{"ref":"NSL 1 § 1 st. 2","text":"1 § Den som olovligen 1. överlåter narkotika, 2. framställer narkotika som är avsedd för missbruk, 3. förvärvar narkotika i överlåtelsesyfte, 4. anskaffar, bearbetar, förpackar, transporterar, förvarar eller tar annan sådan befattning med narkotika som inte är avsedd för eget bruk, eller 5. innehar, brukar eller tar annan befattning med narkotika döms för narkotikabrott till fängelse i högst tre år. Om en gärning som avses i första stycket innebär att gärningsmannen säljer narkotika eller annars befattar sig med narkotika som är avsedd att säljas, döms i stället till fängelse i lägst sex månader och högst tre år. För narkotikabrott döms även den som olovligen bjuder ut narkotika till försäljning, förvarar eller befordrar vederlag för narkotika, förmedlar kontakter mellan säljare och köpare eller företar någon annan sådan åtgärd, om förfarandet är ägnat att främja narkotikahandel. Straffet är i ett sådant fall fängelse i lägst sex månader och högst tre år. Bestämmelser om straff för olovlig införsel och utförsel av narkotika och olovlig befattning i vissa fall med narkotika finns i lagen (2000:1225) om straff för smuggling. Lag (2023:258)."},"Narkotikabrott · förvärv i överlåtelsesyfte":{"ref":"NSL 1 § 1 st. 3","text":"1 § Den som olovligen 1. överlåter narkotika, 2. framställer narkotika som är avsedd för missbruk, 3. förvärvar narkotika i överlåtelsesyfte, 4. anskaffar, bearbetar, förpackar, transporterar, förvarar eller tar annan sådan befattning med narkotika som inte är avsedd för eget bruk, eller 5. innehar, brukar eller tar annan befattning med narkotika döms för narkotikabrott till fängelse i högst tre år. Om en gärning som avses i första stycket innebär att gärningsmannen säljer narkotika eller annars befattar sig med narkotika som är avsedd att säljas, döms i stället till fängelse i lägst sex månader och högst tre år. För narkotikabrott döms även den som olovligen bjuder ut narkotika till försäljning, förvarar eller befordrar vederlag för narkotika, förmedlar kontakter mellan säljare och köpare eller företar någon annan sådan åtgärd, om förfarandet är ägnat att främja narkotikahandel. Straffet är i ett sådant fall fängelse i lägst sex månader och högst tre år. Bestämmelser om straff för olovlig införsel och utförsel av narkotika och olovlig befattning i vissa fall med narkotika finns i lagen (2000:1225) om straff för smuggling. Lag (2023:258)."},"Narkotikabrott · transport/förvaring":{"ref":"NSL 1 § 1 st. 4","text":"1 § Den som olovligen 1. överlåter narkotika, 2. framställer narkotika som är avsedd för missbruk, 3. förvärvar narkotika i överlåtelsesyfte, 4. anskaffar, bearbetar, förpackar, transporterar, förvarar eller tar annan sådan befattning med narkotika som inte är avsedd för eget bruk, eller 5. innehar, brukar eller tar annan befattning med narkotika döms för narkotikabrott till fängelse i högst tre år. Om en gärning som avses i första stycket innebär att gärningsmannen säljer narkotika eller annars befattar sig med narkotika som är avsedd att säljas, döms i stället till fängelse i lägst sex månader och högst tre år. För narkotikabrott döms även den som olovligen bjuder ut narkotika till försäljning, förvarar eller befordrar vederlag för narkotika, förmedlar kontakter mellan säljare och köpare eller företar någon annan sådan åtgärd, om förfarandet är ägnat att främja narkotikahandel. Straffet är i ett sådant fall fängelse i lägst sex månader och högst tre år. Bestämmelser om straff för olovlig införsel och utförsel av narkotika och olovlig befattning i vissa fall med narkotika finns i lagen (2000:1225) om straff för smuggling. Lag (2023:258)."},"Narkotikabrott · försäljning":{"ref":"NSL 1 § 2 st.","text":"1 § Den som olovligen 1. överlåter narkotika, 2. framställer narkotika som är avsedd för missbruk, 3. förvärvar narkotika i överlåtelsesyfte, 4. anskaffar, bearbetar, förpackar, transporterar, förvarar eller tar annan sådan befattning med narkotika som inte är avsedd för eget bruk, eller 5. innehar, brukar eller tar annan befattning med narkotika döms för narkotikabrott till fängelse i högst tre år. Om en gärning som avses i första stycket innebär att gärningsmannen säljer narkotika eller annars befattar sig med narkotika som är avsedd att säljas, döms i stället till fängelse i lägst sex månader och högst tre år. För narkotikabrott döms även den som olovligen bjuder ut narkotika till försäljning, förvarar eller befordrar vederlag för narkotika, förmedlar kontakter mellan säljare och köpare eller företar någon annan sådan åtgärd, om förfarandet är ägnat att främja narkotikahandel. Straffet är i ett sådant fall fängelse i lägst sex månader och högst tre år. Bestämmelser om straff för olovlig införsel och utförsel av narkotika och olovlig befattning i vissa fall med narkotika finns i lagen (2000:1225) om straff för smuggling. Lag (2023:258)."},"Narkotikabrott · främjande av handel":{"ref":"NSL 1 § 3 st.","text":"1 § Den som olovligen 1. överlåter narkotika, 2. framställer narkotika som är avsedd för missbruk, 3. förvärvar narkotika i överlåtelsesyfte, 4. anskaffar, bearbetar, förpackar, transporterar, förvarar eller tar annan sådan befattning med narkotika som inte är avsedd för eget bruk, eller 5. innehar, brukar eller tar annan befattning med narkotika döms för narkotikabrott till fängelse i högst tre år. Om en gärning som avses i första stycket innebär att gärningsmannen säljer narkotika eller annars befattar sig med narkotika som är avsedd att säljas, döms i stället till fängelse i lägst sex månader och högst tre år. För narkotikabrott döms även den som olovligen bjuder ut narkotika till försäljning, förvarar eller befordrar vederlag för narkotika, förmedlar kontakter mellan säljare och köpare eller företar någon annan sådan åtgärd, om förfarandet är ägnat att främja narkotikahandel. Straffet är i ett sådant fall fängelse i lägst sex månader och högst tre år. Bestämmelser om straff för olovlig införsel och utförsel av narkotika och olovlig befattning i vissa fall med narkotika finns i lagen (2000:1225) om straff för smuggling. Lag (2023:258)."},"Ringa narkotikabrott · innehav":{"ref":"NSL 2 § jfr 1 §","text":"2 § Är brott som avses i 1 § första stycket med hänsyn till arten och mängden narkotika samt övriga omständigheter att anse som ringa, döms för ringa narkotikabrott till böter eller fängelse i högst sex månader. Lag (2016:488)."},"Grovt narkotikabrott":{"ref":"NSL 3 §","text":"3 § Är brott som avses i 1 § att anse som grovt, döms för grovt narkotikabrott till fängelse i lägst två och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om brottet har utgjort ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, avsett en särskilt stor mängd narkotika eller annars varit av särskilt farlig eller hänsynslös art. Är brottet att anse som synnerligen grovt, döms för synnerligen grovt narkotikabrott till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om brottet har utgjort ett led i en verksamhet som utövats i organiserad form i syfte att i stor omfattning bedriva handel med narkotika, avsett en synnerligen stor mängd narkotika eller annars varit av synnerligen farlig eller hänsynslös art. Lag (2023:258)."},"Synnerligen grovt narkotikabrott":{"ref":"NSL 3 § 2 st.","text":"3 § Är brott som avses i 1 § att anse som grovt, döms för grovt narkotikabrott till fängelse i lägst två och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om brottet har utgjort ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, avsett en särskilt stor mängd narkotika eller annars varit av särskilt farlig eller hänsynslös art. Är brottet att anse som synnerligen grovt, döms för synnerligen grovt narkotikabrott till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om brottet har utgjort ett led i en verksamhet som utövats i organiserad form i syfte att i stor omfattning bedriva handel med narkotika, avsett en synnerligen stor mängd narkotika eller annars varit av synnerligen farlig eller hänsynslös art. Lag (2023:258)."},"Vapenbrott":{"ref":"VapenL 18:1","text":"18 kap. 1 § Den som uppsåtligen innehar eller tillverkar ett skjutvapen utan att ha rätt till det eller överlåter, yrkesmässigt förmedlar eller lånar ut ett skjutvapen till någon som inte har rätt att inneha vapnet döms för vapenbrott till fängelse i högst fem år. Om brottet med hänsyn till risken för att vapnet skulle komma till brottslig eller annan skadlig användning och övriga omständigheter är att anse som mindre allvarligt, döms till böter eller fängelse i högst sex månader. Till böter eller fängelse i högst sex månader döms också den som har begått gärningen av oaktsamhet. Lag (2026:1250)."},"Mindre allvarligt vapenbrott":{"ref":"VapenL 18:1 st. 2","text":"18 kap. 1 § Den som uppsåtligen innehar eller tillverkar ett skjutvapen utan att ha rätt till det eller överlåter, yrkesmässigt förmedlar eller lånar ut ett skjutvapen till någon som inte har rätt att inneha vapnet döms för vapenbrott till fängelse i högst fem år. Om brottet med hänsyn till risken för att vapnet skulle komma till brottslig eller annan skadlig användning och övriga omständigheter är att anse som mindre allvarligt, döms till böter eller fängelse i högst sex månader. Till böter eller fängelse i högst sex månader döms också den som har begått gärningen av oaktsamhet. Lag (2026:1250)."},"Vapenbrott av oaktsamhet":{"ref":"VapenL 18:1 st. 3","text":"18 kap. 1 § Den som uppsåtligen innehar eller tillverkar ett skjutvapen utan att ha rätt till det eller överlåter, yrkesmässigt förmedlar eller lånar ut ett skjutvapen till någon som inte har rätt att inneha vapnet döms för vapenbrott till fängelse i högst fem år. Om brottet med hänsyn till risken för att vapnet skulle komma till brottslig eller annan skadlig användning och övriga omständigheter är att anse som mindre allvarligt, döms till böter eller fängelse i högst sex månader. Till böter eller fängelse i högst sex månader döms också den som har begått gärningen av oaktsamhet. Lag (2026:1250)."},"Grovt vapenbrott":{"ref":"VapenL 18:2","text":"18 kap. 2 § Om ett brott som avses i 1 § första stycket är grovt, döms för grovt vapenbrott till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. vapnet har innehafts på allmän plats eller på en annan plats där människor brukar samlas eller har samlats eller i ett fordon på en sådan plats, 2. vapnet har varit av särskilt farlig beskaffenhet, 3. innehavet, tillverkningen, överlåtelsen, förmedlingen eller utlåningen har avsett flera vapen, 4. vapnet har innehafts eller tillverkats i en sådan miljö att det typiskt sett kan befaras komma till brottslig användning, eller 5. gärningen annars har varit av särskilt farlig art. Om ett brott som avses i 1 § första stycket är synnerligen grovt, döms för synnerligen grovt vapenbrott till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om innehavet, tillverkningen, överlåtelsen, förmedlingen eller utlåningen har avsett ett stort antal vapen eller flera vapen av särskilt farlig beskaffenhet. Vid bedömningen enligt första och andra styckena ska ett enhandsvapen anses vara av särskilt farlig beskaffenhet, om det är kraftfullt eller har en särskilt farlig konstruktion eller utformning. Lag (2026:1250)."},"Synnerligen grovt vapenbrott":{"ref":"VapenL 18:2 st. 2","text":"18 kap. 2 § Om ett brott som avses i 1 § första stycket är grovt, döms för grovt vapenbrott till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. vapnet har innehafts på allmän plats eller på en annan plats där människor brukar samlas eller har samlats eller i ett fordon på en sådan plats, 2. vapnet har varit av särskilt farlig beskaffenhet, 3. innehavet, tillverkningen, överlåtelsen, förmedlingen eller utlåningen har avsett flera vapen, 4. vapnet har innehafts eller tillverkats i en sådan miljö att det typiskt sett kan befaras komma till brottslig användning, eller 5. gärningen annars har varit av särskilt farlig art. Om ett brott som avses i 1 § första stycket är synnerligen grovt, döms för synnerligen grovt vapenbrott till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om innehavet, tillverkningen, överlåtelsen, förmedlingen eller utlåningen har avsett ett stort antal vapen eller flera vapen av särskilt farlig beskaffenhet. Vid bedömningen enligt första och andra styckena ska ett enhandsvapen anses vara av särskilt farlig beskaffenhet, om det är kraftfullt eller har en särskilt farlig konstruktion eller utformning. Lag (2026:1250)."},"Rattfylleri":{"ref":"TBL 4 §","text":"4 § Den som för ett motordrivet fordon eller en spårvagn efter att ha intagit alkohol i så stor mängd att alkoholkoncentrationen under eller efter färden uppgår till minst 0,2 promille i blodet eller 0,10 milligram per liter i utandningsluften döms för rattfylleri till böter eller fängelse i högst sex månader. För rattfylleri enligt första stycket döms också den som för ett motordrivet fordon eller en spårvagn efter att ha intagit narkotika som avses i 8 § narkotikastrafflagen (1968:64) i så stor mängd att det under eller efter färden finns något narkotiskt ämne kvar i blodet. Detta gäller dock inte om narkotikan intagits i enlighet med läkares eller annan behörig receptutfärdares ordination. För rattfylleri enligt första stycket döms också den som för ett motordrivet fordon eller en spårvagn och då är så påverkad av alkohol att det kan antas att han eller hon inte kan framföra fordonet på ett betryggande sätt. Detsamma gäller om föraren är lika påverkad av något annat medel. Första och andra styckena gäller inte förare av ett motordrivet fordon, som är avsett att föras av gående. Första, andra och tredje styckena gäller inte om förandet av fordonet ingår som ett led i en vetenskaplig eller därmed jämförlig undersökning till vilken tillstånd har lämnats av regeringen eller den myndighet som regeringen bestämmer. Lag (2019:346)."},"Grovt rattfylleri":{"ref":"TBL 4 a §","text":"4 a § Är ett brott som avses i 4 § första, andra eller tredje stycket att anse som grovt, skall föraren dömas för grovt rattfylleri till fängelse i högst två år. Vid bedömande av om brottet är grovt skall särskilt beaktas om 1. föraren har haft en alkoholkoncentration som uppgått till minst 1,0 promille i blodet eller 0,50 milligram per liter i utandningsluften, 2. föraren annars har varit avsevärt påverkad av alkohol eller något annat medel, eller 3. framförandet av fordonet har inneburit en påtaglig fara för trafiksäkerheten. Lag (1999:217)."},"Olovlig körning":{"ref":"TBL 3 §","text":"3 § För någon uppsåtligen körkortspliktigt fordon utan att vara berättigad att föra sådant fordon, dömes för olovlig körning till böter. Har han tidigare innehaft körkort som blivit återkallat eller har brottet skett vanemässigt eller är det eljest att anse som grovt, må dömas till fängelse i högst sex månader. För någon körkortspliktigt fordon med uppsåtligt eller oaktsamt åsidosättande av föreskrift, som meddelats i fråga om rätten att föra sådant fordon, dömes till böter. Om någon uppsåtligen eller av oaktsamhet såsom förare av körkortspliktigt fordon anställer och brukar den som inte äger rätt att föra fordonet, eller i annat fall tillåter någon annan att föra sådant fordon utan att denne är berättigad därtill, dömes likaledes till böter. Första-tredje styckena äger motsvarande tillämpning på förare av traktor, moped klass II, snöskoter, terränghjuling, motorredskap eller spårvagn och på den som anställer eller brukar sådan förare eller eljest tillåter någon att föra sådant fordon. Lag (2009:122)."},"Grov olovlig körning":{"ref":"TBL 3 §","text":"3 § För någon uppsåtligen körkortspliktigt fordon utan att vara berättigad att föra sådant fordon, dömes för olovlig körning till böter. Har han tidigare innehaft körkort som blivit återkallat eller har brottet skett vanemässigt eller är det eljest att anse som grovt, må dömas till fängelse i högst sex månader. För någon körkortspliktigt fordon med uppsåtligt eller oaktsamt åsidosättande av föreskrift, som meddelats i fråga om rätten att föra sådant fordon, dömes till böter. Om någon uppsåtligen eller av oaktsamhet såsom förare av körkortspliktigt fordon anställer och brukar den som inte äger rätt att föra fordonet, eller i annat fall tillåter någon annan att föra sådant fordon utan att denne är berättigad därtill, dömes likaledes till böter. Första-tredje styckena äger motsvarande tillämpning på förare av traktor, moped klass II, snöskoter, terränghjuling, motorredskap eller spårvagn och på den som anställer eller brukar sådan förare eller eljest tillåter någon att föra sådant fordon. Lag (2009:122)."},"Brott mot knivlagen":{"ref":"KnivL 4 § jfr 1 §","text":"4 § Den som uppsåtligen bryter mot 1 eller 2 § döms till böter eller fängelse i högst ett år. Om gärningen har begåtts av oaktsamhet, döms till böter eller fängelse i högst sex månader. Om ett brott som avses i första stycket är grovt, döms till fängelse i lägst sex månader och högst två år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. föremålet har innehafts i ett sammanhang där det kan befaras komma till användning vid brottsligt angrepp på någons liv, hälsa eller trygghet till person, 2. föremålet har varit av särskilt farlig beskaffenhet, 3. innehavet, överlåtelsen eller saluhållandet har avsett flera föremål, eller 4. gärningen på annat sätt har varit av särskilt farlig art. Om det rör sig om ringa fall utgör gärningen dock inte brott. Lag (2022:608)."},"Grovt brott mot knivlagen":{"ref":"KnivL 4 § st. 3","text":"4 § Den som uppsåtligen bryter mot 1 eller 2 § döms till böter eller fängelse i högst ett år. Om gärningen har begåtts av oaktsamhet, döms till böter eller fängelse i högst sex månader. Om ett brott som avses i första stycket är grovt, döms till fängelse i lägst sex månader och högst två år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. föremålet har innehafts i ett sammanhang där det kan befaras komma till användning vid brottsligt angrepp på någons liv, hälsa eller trygghet till person, 2. föremålet har varit av särskilt farlig beskaffenhet, 3. innehavet, överlåtelsen eller saluhållandet har avsett flera föremål, eller 4. gärningen på annat sätt har varit av särskilt farlig art. Om det rör sig om ringa fall utgör gärningen dock inte brott. Lag (2022:608)."},"Bidragsbrott":{"ref":"BidrBrL 2","text":"2 § Den som lämnar oriktiga uppgifter eller inte anmäler ändrade förhållanden som han eller hon är skyldig att anmäla enligt lag eller förordning, och på så sätt orsakar fara för att en ekonomisk förmån eller ett ekonomiskt stöd felaktigt betalas ut, felaktigt tillgodoräknas, betalas ut med ett för högt belopp eller tillgodoräknas med ett för högt belopp, döms för bidragsbrott till fängelse i högst två år eller, om brottet är ringa, till böter eller fängelse i högst sex månader. Lag (2019:652)."},"Ringa bidragsbrott":{"ref":"BidrBrL 2","text":"2 § Den som lämnar oriktiga uppgifter eller inte anmäler ändrade förhållanden som han eller hon är skyldig att anmäla enligt lag eller förordning, och på så sätt orsakar fara för att en ekonomisk förmån eller ett ekonomiskt stöd felaktigt betalas ut, felaktigt tillgodoräknas, betalas ut med ett för högt belopp eller tillgodoräknas med ett för högt belopp, döms för bidragsbrott till fängelse i högst två år eller, om brottet är ringa, till böter eller fängelse i högst sex månader. Lag (2019:652)."},"Grovt bidragsbrott":{"ref":"BidrBrL 3","text":"3 § Om brott som avses i 2 § är grovt, döms för grovt bidragsbrott till fängelse i lägst ett och högst sex år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. brottet rört betydande belopp, 2. den som begått brottet använt falska handlingar, eller 3. gärningen ingått i en brottslighet som utövats systematiskt eller i större omfattning. Lag (2026:1322)."},"Vårdslöst bidragsbrott":{"ref":"BidrBrL 4","text":"4 § Den som av grov oaktsamhet begår en sådan gärning som avses i 2 §, döms för vårdslöst bidragsbrott till böter eller fängelse i högst ett år. Om gärningen med hänsyn till beloppet, risken för slutlig ekonomisk skada och övriga omständigheter är mindre allvarlig, döms inte till ansvar. Lag (2019:652)."},"Skattebrott":{"ref":"SkBrL 2","text":"2 § Den som uppsåtligen lämnar oriktig uppgift till en myndighet eller låter bli att till en myndighet lämna deklaration, kontrolluppgift eller annan föreskriven uppgift och därigenom ger upphov till fara för att skatt undandras det allmänna eller felaktigt tillgodoräknas eller återbetalas till personen själv eller annan, döms för skattebrott till fängelse i högst två år. Lag (2026:109)."},"Skatteförseelse":{"ref":"SkBrL 3","text":"3 § Om brott som avses i 2 § är att anse som ringa, döms för skatteförseelse till böter. Lag (1996:658)."},"Grovt skattebrott":{"ref":"SkBrL 4","text":"4 § Om brott som avses i 2 § är att anse som grovt, döms för grovt skattebrott till fängelse i lägst ett och högst sex år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om det rört mycket betydande belopp, om gärningsmannen använt falska handlingar eller vilseledande bokföring eller om förfarandet ingått som ett led i en brottslighet som utövats systematiskt eller i större omfattning eller i annat fall varit av synnerligen farlig art. Lag (2026:1320)."},"Vårdslös skatteuppgift":{"ref":"SkBrL 5","text":"5 § Den som av grov oaktsamhet lämnar oriktig uppgift till en myndighet och därigenom ger upphov till fara för att skatt undandras det allmänna eller felaktigt tillgodoräknas eller återbetalas till uppgiftslämnaren eller annan döms för vårdslös skatteuppgift till böter eller fängelse i högst ett år. Om gärningen med hänsyn till skattebeloppet och övriga omständigheter är av mindre allvarlig art, ska det inte dömas till ansvar enligt första stycket. Lag (2026:109)."},"Skatteavdragsbrott":{"ref":"SkBrL 6","text":"6 § Den som uppsåtligen eller av grov oaktsamhet underlåter att fullgöra skyldighet att göra skatteavdrag på sätt som föreskrivs i skatteförfarandelagen (2011:1244) döms för skatteavdragsbrott till böter eller fängelse i högst ett år. I ringa fall ska inte dömas till ansvar enligt första stycket. Lag (2011:1247)."},"Skatteredovisningsbrott":{"ref":"SkBrL 7","text":"7 § Den som, i annat fall än som avses i 2 §, uppsåtligen lämnar oriktig uppgift till 1. en myndighet, om uppgiften rör förhållande som har betydelse för skyldigheten för uppgiftslämnaren eller annan att betala skatt, 2. någon som är skyldig att för henne eller honom innehålla skatt eller lämna kontrolluppgift eller motsvarande underrättelse, om uppgiften rör förhållande som har betydelse för skyldighetens fullgörande eller för skyldigheten för uppgiftslämnaren eller annan att betala skatt, döms för skatteredovisningsbrott till böter eller fängelse i högst sex månader. Detsamma gäller den som, i annat fall än som avses i 2 §, uppsåtligen låter bli att lämna en föreskriven uppgift angående sådant förhållande som anges i första stycket 1 eller 2 till någon som avses där. Detta gäller dock endast under förutsättning att uppgiften ska lämnas utan föreläggande eller uppmaning och inte avser egen inkomstdeklaration. I ringa fall ska det inte dömas till ansvar enligt första eller andra stycket. Lag (2026:109)."},"Vårdslös skatteredovisning":{"ref":"SkBrL 8","text":"8 § Den som av grov oaktsamhet begår en gärning som avses i 7 § första stycket 2 eller andra stycket döms för vårdslös skatteredovisning till böter eller fängelse i högst sex månader. I ringa fall ska det inte dömas till ansvar enligt första stycket. Lag (2026:109)."},"Försvårande av skattekontroll":{"ref":"SkBrL 10","text":"10 § Den som uppsåtligen eller av grov oaktsamhet åsidosätter bokföringsskyldighet eller sådan skyldighet att föra och bevara räkenskaper, som föreskrivs för vissa uppgiftsskyldiga och därigenom ger upphov till fara för att myndighets kontrollverksamhet vid beräkning eller uppbörd av skatt eller avgift allvarligt försvåras, döms för försvårande av skattekontroll till böter eller fängelse i högst två år eller, om brottet är grovt, till fängelse i lägst sex månader och högst fyra år. I ringa fall ska det inte dömas till ansvar enligt första stycket. Lag (2026:109)."},"Grovt försvårande av skattekontroll":{"ref":"SkBrL 10","text":"10 § Den som uppsåtligen eller av grov oaktsamhet åsidosätter bokföringsskyldighet eller sådan skyldighet att föra och bevara räkenskaper, som föreskrivs för vissa uppgiftsskyldiga och därigenom ger upphov till fara för att myndighets kontrollverksamhet vid beräkning eller uppbörd av skatt eller avgift allvarligt försvåras, döms för försvårande av skattekontroll till böter eller fängelse i högst två år eller, om brottet är grovt, till fängelse i lägst sex månader och högst fyra år. I ringa fall ska det inte dömas till ansvar enligt första stycket. Lag (2026:109)."},"Smuggling":{"ref":"SmuglL 3","text":"3 § Den som, i samband med införsel till landet av en vara som omfattas av ett särskilt föreskrivet förbud mot eller villkor för införsel, uppsåtligen bryter mot förbudet eller villkoret genom att underlåta att anmäla varan till tullbehandling, döms för smuggling till böter eller fängelse i högst två år. Det som föreskrivs i första stycket gäller också den som, i samband med att en sådan vara förs in till landet, uppsåtligen lämnar oriktig uppgift vid tullbehandling eller underlåter att lämna föreskriven uppgift vid tullbehandling och därigenom ger upphov till fara för att införseln fullföljs i strid med förbudet eller villkoret. För smuggling döms också den som uppsåtligen 1. från landet för ut en vara i strid med ett särskilt föreskrivet förbud mot eller villkor för utförsel eller efter utförseln förfogar över varan i strid med förbudet eller villkoret, 2. under pågående tullbehandling förfogar över en vara som omfattas av ett särskilt föreskrivet förbud mot eller villkor för införsel och därigenom föranleder att införseln fullföljs i strid med förbudet eller villkoret, 3. till landet för in eller från landet för ut en vara med stöd av ett tillstånd som föranletts av att någon lämnat oriktig uppgift eller underlåtit att lämna föreskriven uppgift till en tillståndsmyndighet eller förfar på ett sådant sätt hos en tillståndsmyndighet och därigenom föranleder att tillstånd meddelas och att varan förs in till eller ut från landet med stöd av tillståndet, eller 4. förfogar över en vara i strid med villkor som uppställts för eller i samband med varans införsel eller utförsel. I det fall bestämmelserna om tullbehandling inte är tillämpliga vid införsel från eller utförsel till ett annat EU-land, gäller det som anges i första och andra styckena om tullbehandling i stället för förfaranden enligt inregränslagen (1996:701). Lag (2024:739) ."},"Ringa smuggling":{"ref":"SmuglL 4","text":"4 § Om ett brott som avses i 3 § är att anse som ringa, döms till penningböter."},"Grov smuggling":{"ref":"SmuglL 5","text":"5 § Om ett brott som avses i 3 § är att anse som grovt, döms för grov smuggling till fängelse i lägst ett och högst sex år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen ingått som ett led i en brottslighet som utövats systematiskt eller i större omfattning, om gärningen med hänsyn till omständigheterna kring införseln, utförseln eller förfogandet varit av särskilt farlig art eller om gärningen annars inneburit en allvarlig kränkning av ett betydande samhällsintresse. Lag (2026:1321) ."},"Narkotikasmuggling":{"ref":"SmuglL 6","text":"6 § Om en gärning som avses i 3 § gäller narkotika, döms för narkotikasmuggling till fängelse i högst tre år. Om narkotikan är avsedd att säljas, döms till fängelse i lägst sex månader och högst tre år. Om brott som avses i första stycket är ringa, döms för ringa narkotikasmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov narkotikasmuggling till fängelse i lägst två och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen avsett en särskilt stor mängd narkotika, om gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller om verksamheten eller gärningen annars varit av särskilt farlig eller hänsynslös art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov narkotikasmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen har ingått som ett led i en verksamhet som utövats i organiserad form i syfte att i stor omfattning bedriva handel med narkotika, om gärningen avsett en synnerligen stor mängd narkotika, eller om verksamheten eller gärningen annars varit av synnerligen farlig eller hänsynslös art. Lag (2025:645) ."},"Narkotikasmuggling – avsedd att säljas":{"ref":"SmuglL 6","text":"6 § Om en gärning som avses i 3 § gäller narkotika, döms för narkotikasmuggling till fängelse i högst tre år. Om narkotikan är avsedd att säljas, döms till fängelse i lägst sex månader och högst tre år. Om brott som avses i första stycket är ringa, döms för ringa narkotikasmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov narkotikasmuggling till fängelse i lägst två och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen avsett en särskilt stor mängd narkotika, om gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller om verksamheten eller gärningen annars varit av särskilt farlig eller hänsynslös art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov narkotikasmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen har ingått som ett led i en verksamhet som utövats i organiserad form i syfte att i stor omfattning bedriva handel med narkotika, om gärningen avsett en synnerligen stor mängd narkotika, eller om verksamheten eller gärningen annars varit av synnerligen farlig eller hänsynslös art. Lag (2025:645) ."},"Ringa narkotikasmuggling":{"ref":"SmuglL 6","text":"6 § Om en gärning som avses i 3 § gäller narkotika, döms för narkotikasmuggling till fängelse i högst tre år. Om narkotikan är avsedd att säljas, döms till fängelse i lägst sex månader och högst tre år. Om brott som avses i första stycket är ringa, döms för ringa narkotikasmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov narkotikasmuggling till fängelse i lägst två och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen avsett en särskilt stor mängd narkotika, om gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller om verksamheten eller gärningen annars varit av särskilt farlig eller hänsynslös art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov narkotikasmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen har ingått som ett led i en verksamhet som utövats i organiserad form i syfte att i stor omfattning bedriva handel med narkotika, om gärningen avsett en synnerligen stor mängd narkotika, eller om verksamheten eller gärningen annars varit av synnerligen farlig eller hänsynslös art. Lag (2025:645) ."},"Grov narkotikasmuggling":{"ref":"SmuglL 6","text":"6 § Om en gärning som avses i 3 § gäller narkotika, döms för narkotikasmuggling till fängelse i högst tre år. Om narkotikan är avsedd att säljas, döms till fängelse i lägst sex månader och högst tre år. Om brott som avses i första stycket är ringa, döms för ringa narkotikasmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov narkotikasmuggling till fängelse i lägst två och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen avsett en särskilt stor mängd narkotika, om gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller om verksamheten eller gärningen annars varit av särskilt farlig eller hänsynslös art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov narkotikasmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen har ingått som ett led i en verksamhet som utövats i organiserad form i syfte att i stor omfattning bedriva handel med narkotika, om gärningen avsett en synnerligen stor mängd narkotika, eller om verksamheten eller gärningen annars varit av synnerligen farlig eller hänsynslös art. Lag (2025:645) ."},"Synnerligen grov narkotikasmuggling":{"ref":"SmuglL 6","text":"6 § Om en gärning som avses i 3 § gäller narkotika, döms för narkotikasmuggling till fängelse i högst tre år. Om narkotikan är avsedd att säljas, döms till fängelse i lägst sex månader och högst tre år. Om brott som avses i första stycket är ringa, döms för ringa narkotikasmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov narkotikasmuggling till fängelse i lägst två och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen avsett en särskilt stor mängd narkotika, om gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller om verksamheten eller gärningen annars varit av särskilt farlig eller hänsynslös art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov narkotikasmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen har ingått som ett led i en verksamhet som utövats i organiserad form i syfte att i stor omfattning bedriva handel med narkotika, om gärningen avsett en synnerligen stor mängd narkotika, eller om verksamheten eller gärningen annars varit av synnerligen farlig eller hänsynslös art. Lag (2025:645) ."},"Vapensmuggling":{"ref":"SmuglL 6 a","text":"6 a § Om en gärning som avses i 3 § gäller vapen, döms för vapensmuggling till fängelse i högst fem år. Om brottet är ringa, döms för ringa vapensmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov vapensmuggling till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett ett vapen av särskilt farlig beskaffenhet, 2. gärningen avsett flera vapen, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov vapensmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal vapen eller flera vapen av särskilt farlig beskaffenhet. Vid bedömningen enligt tredje och fjärde styckena ska ett enhandsvapen anses vara av särskilt farlig beskaffenhet, om det är kraftfullt eller har en särskilt farlig konstruktion eller utformning. Lag (2023:873) ."},"Ringa vapensmuggling":{"ref":"SmuglL 6 a","text":"6 a § Om en gärning som avses i 3 § gäller vapen, döms för vapensmuggling till fängelse i högst fem år. Om brottet är ringa, döms för ringa vapensmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov vapensmuggling till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett ett vapen av särskilt farlig beskaffenhet, 2. gärningen avsett flera vapen, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov vapensmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal vapen eller flera vapen av särskilt farlig beskaffenhet. Vid bedömningen enligt tredje och fjärde styckena ska ett enhandsvapen anses vara av särskilt farlig beskaffenhet, om det är kraftfullt eller har en särskilt farlig konstruktion eller utformning. Lag (2023:873) ."},"Grov vapensmuggling":{"ref":"SmuglL 6 a","text":"6 a § Om en gärning som avses i 3 § gäller vapen, döms för vapensmuggling till fängelse i högst fem år. Om brottet är ringa, döms för ringa vapensmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov vapensmuggling till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett ett vapen av särskilt farlig beskaffenhet, 2. gärningen avsett flera vapen, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov vapensmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal vapen eller flera vapen av särskilt farlig beskaffenhet. Vid bedömningen enligt tredje och fjärde styckena ska ett enhandsvapen anses vara av särskilt farlig beskaffenhet, om det är kraftfullt eller har en särskilt farlig konstruktion eller utformning. Lag (2023:873) ."},"Synnerligen grov vapensmuggling":{"ref":"SmuglL 6 a","text":"6 a § Om en gärning som avses i 3 § gäller vapen, döms för vapensmuggling till fängelse i högst fem år. Om brottet är ringa, döms för ringa vapensmuggling till böter eller fängelse i högst sex månader. Om brottet är att anse som grovt, döms för grov vapensmuggling till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett ett vapen av särskilt farlig beskaffenhet, 2. gärningen avsett flera vapen, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov vapensmuggling till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal vapen eller flera vapen av särskilt farlig beskaffenhet. Vid bedömningen enligt tredje och fjärde styckena ska ett enhandsvapen anses vara av särskilt farlig beskaffenhet, om det är kraftfullt eller har en särskilt farlig konstruktion eller utformning. Lag (2023:873) ."},"Smuggling av explosiv vara":{"ref":"SmuglL 6 b","text":"6 b § Om en gärning som avses i 3 § gäller explosiva varor, döms för smuggling av explosiv vara till böter eller fängelse i högst fem år. Om brottet är ringa, döms för ringa smuggling av explosiv vara till penningböter. Om brottet är att anse som grovt, döms för grov smuggling av explosiv vara till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett en vara som med hänsyn till dess effekt, konstruktion eller utformning har varit av särskilt farlig beskaffenhet, 2. gärningen avsett flera varor eller en stor mängd av en vara, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov smuggling av explosiv vara till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal varor eller en särskilt stor mängd av en vara eller flera varor av särskilt farlig beskaffenhet eller en stor mängd av en vara av särskilt farlig beskaffenhet. Lag (2023:873) ."},"Ringa smuggling av explosiv vara":{"ref":"SmuglL 6 b","text":"6 b § Om en gärning som avses i 3 § gäller explosiva varor, döms för smuggling av explosiv vara till böter eller fängelse i högst fem år. Om brottet är ringa, döms för ringa smuggling av explosiv vara till penningböter. Om brottet är att anse som grovt, döms för grov smuggling av explosiv vara till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett en vara som med hänsyn till dess effekt, konstruktion eller utformning har varit av särskilt farlig beskaffenhet, 2. gärningen avsett flera varor eller en stor mängd av en vara, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov smuggling av explosiv vara till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal varor eller en särskilt stor mängd av en vara eller flera varor av särskilt farlig beskaffenhet eller en stor mängd av en vara av särskilt farlig beskaffenhet. Lag (2023:873) ."},"Grov smuggling av explosiv vara":{"ref":"SmuglL 6 b","text":"6 b § Om en gärning som avses i 3 § gäller explosiva varor, döms för smuggling av explosiv vara till böter eller fängelse i högst fem år. Om brottet är ringa, döms för ringa smuggling av explosiv vara till penningböter. Om brottet är att anse som grovt, döms för grov smuggling av explosiv vara till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett en vara som med hänsyn till dess effekt, konstruktion eller utformning har varit av särskilt farlig beskaffenhet, 2. gärningen avsett flera varor eller en stor mängd av en vara, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov smuggling av explosiv vara till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal varor eller en särskilt stor mängd av en vara eller flera varor av särskilt farlig beskaffenhet eller en stor mängd av en vara av särskilt farlig beskaffenhet. Lag (2023:873) ."},"Synnerligen grov smuggling av explosiv vara":{"ref":"SmuglL 6 b","text":"6 b § Om en gärning som avses i 3 § gäller explosiva varor, döms för smuggling av explosiv vara till böter eller fängelse i högst fem år. Om brottet är ringa, döms för ringa smuggling av explosiv vara till penningböter. Om brottet är att anse som grovt, döms för grov smuggling av explosiv vara till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. gärningen avsett en vara som med hänsyn till dess effekt, konstruktion eller utformning har varit av särskilt farlig beskaffenhet, 2. gärningen avsett flera varor eller en stor mängd av en vara, 3. gärningen ingått som ett led i en verksamhet som bedrivits i större omfattning eller yrkesmässigt, eller 4. verksamheten eller gärningen annars varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt, döms för synnerligen grov smuggling av explosiv vara till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om gärningen avsett ett stort antal varor eller en särskilt stor mängd av en vara eller flera varor av särskilt farlig beskaffenhet eller en stor mängd av en vara av särskilt farlig beskaffenhet. Lag (2023:873) ."},"Olovlig införsel eller utförsel":{"ref":"SmuglL 7","text":"7 § Den som av grov oaktsamhet begår en gärning som avses i 3, 6, 6 a eller 6 b §, döms för olovlig införsel eller olovlig utförsel till böter eller fängelse i högst två år. För olovlig införsel eller olovlig utförsel döms också den som av grov oaktsamhet 1. i samband med utförsel från landet av en vara underlåter att anmäla varan till tullbehandling, lämnar oriktig uppgift vid tullbehandling eller underlåter att lämna föreskriven uppgift vid tullbehandling och därigenom ger upphov till fara för att sådant förbud eller villkor som avses i 3 § tredje stycket 1 eller den bestämmelsen tillsammans med 6, 6 a eller 6 b § överträds, eller 2. lämnar oriktig uppgift eller underlåter att lämna föreskriven uppgift i samband med ansökan om sådant tillstånd som avses i 3 § tredje stycket 3 eller den bestämmelsen tillsammans med 6, 6 a eller 6 b § och därigenom ger upphov till fara för att varan förs in eller ut med stöd av detta tillstånd. I de fall bestämmelserna om tullbehandling inte är tillämpliga vid utförsel till ett annat EU-land, gäller vad som anges i andra stycket 1 om tullbehandling i stället för förfaranden enligt inregränslagen (1996:701). Om gärningen är ringa, ska den inte medföra ansvar. Lag (2024:739) ."},"Tullbrott":{"ref":"SmuglL 8","text":"8 § Den som, i samband med att en vara förs in till landet, uppsåtligen underlåter att anmäla varan till tullbehandling, lämnar oriktig uppgift vid tullbehandling eller underlåter att lämna föreskriven uppgift vid tullbehandling och därigenom ger upphov till fara för att tull, annan skatt eller avgift undandras det allmänna, döms för tullbrott till böter eller fängelse i högst två år. För tullbrott döms också den som uppsåtligen ger upphov till fara för att tull, annan skatt eller avgift undandras det allmänna eller felaktigt tillgodoräknas eller återbetalas till honom själv eller annan genom att 1. i samband med att en vara förs ut från landet, förfara så som anges i första stycket eller, efter utförseln, förfoga över varan i strid med vad som förutsatts vid den tullbehandling som skett med anledning av utförseln, 2. under pågående tullbehandling förfoga över en införd vara i strid med vad som gäller för denna tullbehandling, eller 3. bryta mot villkor som vid tullbehandling för övergång till fri omsättning har uppställts för befrielse från eller nedsättning av skatten eller avgiften. Om en tulldeklaration ges in i ett annat EU-land med stöd av ett tillstånd för centraliserad klarering enligt artikel 179 i Europaparlamentets och rådets förordning (EU) nr 952/2013 av den 9 oktober 2013 om fastställande av en tullkodex för unionen, gäller första stycket sådana uppgifter som avses i 2 kap. 2 a § andra stycket tullagen (2016:253). Denna bestämmelse är tillämplig endast i fråga om sådana tullar, andra skatter och avgifter som Tullverket ska besluta. Lag (2021:1152) ."},"Ringa tullbrott":{"ref":"SmuglL 9","text":"9 § Om ett brott som avses i 8 § är att anse som ringa, döms till penningböter."},"Grovt tullbrott":{"ref":"SmuglL 10","text":"10 § Om ett brott som avses i 8 § är att anse som grovt, döms för grovt tullbrott till fängelse i lägst ett och högst sex år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen rört mycket betydande belopp, om gärningsmannen använt falska handlingar eller vilseledande bokföring, om gärningen ingått som ett led i en brottslighet som utövats systematiskt eller i större omfattning eller om gärningen annars varit av särskilt farlig art. Lag (2026:1321) ."},"Vårdslös tullredovisning":{"ref":"SmuglL 11","text":"11 § Den som av grov oaktsamhet begår gärning som avses i 8 §, döms för vårdslös tullredovisning till böter eller fängelse i högst två år. Om gärningen är ringa, skall den inte medföra ansvar."},"Olovlig befattning med smuggelgods":{"ref":"SmuglL 12","text":"12 § Den som uppsåtligen emballerar, transporterar, förvarar, döljer, bearbetar, förvärvar, överlåter eller ingår avtal om upplåtelse av panträtt i en vara som varit föremål för brott enligt 3-11 §§, döms för olovlig befattning med smuggelgods till böter eller fängelse i högst två år. Gärningen ska inte medföra ansvar, om den är ringa med hänsyn till befattningen, omständigheterna kring denna, egendomens beskaffenhet och värde samt övriga omständigheter. Om gärningsmannen inte inser men har skälig anledning att anta att varan varit föremål för brott, döms till böter. Om gärningen är ringa, ska den inte medföra ansvar. Ansvar enligt första eller andra stycket ska inte dömas ut, om gärningen är belagd med straff i - 1 § första stycket 1, 3 eller 4 narkotikastrafflagen (1968:64) eller i 2 eller 3 a § narkotikastrafflagen jämförd med dessa bestämmelser, - 18 kap. 1 eller 2 § vapenlagen (2026:408), eller - 29 § andra stycket 2 eller 29 a § lagen (2010:1011) om brandfarliga och explosiva varor. Lag (2026:417) ."},"Grov olovlig befattning med smuggelgods":{"ref":"SmuglL 13","text":"13 § Om ett brott som avses i 12 § första stycket är att anse som grovt, döms för grov olovlig befattning med smuggelgods till fängelse i lägst ett och högst sex år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen ingått som ett led i en brottslighet som utövats systematiskt eller i större omfattning, om gärningen avsett befattning med varor som varit föremål för brott varigenom tull, annan skatt eller avgift till mycket betydande belopp har undandragits det allmänna eller felaktigt återbetalats eller tillgodoräknats någon eller om gärningen annars varit av särskilt farlig art. Lag (2026:1321) ."},"Penningtvättsbrott":{"ref":"PTBL 3–4","text":"3 § För penningtvättsbrott döms, om åtgärden syftar till att dölja att pengar eller annan egendom härrör från brott eller brottslig verksamhet eller till att främja möjligheterna för någon att tillgodogöra sig egendomen eller dess värde, den som 1. överlåter, förvärvar, omsätter, förvarar eller vidtar annan sådan åtgärd med egendomen, eller 2. tillhandahåller, förvärvar eller upprättar en handling som kan ge en skenbar förklaring till innehavet av egendomen, deltar i transaktioner som utförs för skens skull, uppträder som bulvan eller vidtar annan sådan åtgärd. Straffet är fängelse i högst två år. 4 § För penningtvättsbrott döms även den som, utan att åtgärden har ett sådant syfte som anges i 3 §, otillbörligen främjar möjligheterna för någon att omsätta pengar eller annan egendom som härrör från brott eller brottslig verksamhet."},"Grovt penningtvättsbrott":{"ref":"PTBL 5","text":"5 § Är brott som avses i 3 eller 4 § grovt, döms för grovt penningtvättsbrott till fängelse i lägst ett och högst sex år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om gärningen avsett betydande värden, om de brottsliga åtgärderna har ingått som ett led i en brottslighet som utövats systematiskt eller i större omfattning eller i annat fall varit av särskilt farlig art. Lag (2026:1323) ."},"Penningtvättsförseelse":{"ref":"PTBL 6","text":"6 § Är brott som avses i 3 eller 4 § ringa, döms för penningtvättsförseelse till böter eller fängelse i högst sex månader. För penningtvättsförseelse döms även den som i fall som avses i 3 eller 4 § inte insåg men hade skälig anledning att anta att egendomen härrörde från brott eller brottslig verksamhet."},"Näringspenningtvätt":{"ref":"PTBL 7","text":"7 § Den som, i näringsverksamhet eller såsom led i en verksamhet som bedrivs vanemässigt eller annars i större omfattning, medverkar till en åtgärd som skäligen kan antas vara vidtagen i sådant syfte som anges i 3 §, döms för näringspenningtvätt till fängelse i högst två år. Är brottet grovt, döms till fängelse i lägst ett och högst sex år. Är brottet ringa, döms till böter eller fängelse i högst sex månader. Till samma straff döms den som i annat fall än som anges i första stycket medverkar till en åtgärd som skäligen kan antas vara vidtagen i sådant syfte som anges i 3 §. Lag (2026:1323) ."},"Grov näringspenningtvätt":{"ref":"PTBL 7","text":"7 § Den som, i näringsverksamhet eller såsom led i en verksamhet som bedrivs vanemässigt eller annars i större omfattning, medverkar till en åtgärd som skäligen kan antas vara vidtagen i sådant syfte som anges i 3 §, döms för näringspenningtvätt till fängelse i högst två år. Är brottet grovt, döms till fängelse i lägst ett och högst sex år. Är brottet ringa, döms till böter eller fängelse i högst sex månader. Till samma straff döms den som i annat fall än som anges i första stycket medverkar till en åtgärd som skäligen kan antas vara vidtagen i sådant syfte som anges i 3 §. Lag (2026:1323) ."},"Ringa näringspenningtvätt":{"ref":"PTBL 7","text":"7 § Den som, i näringsverksamhet eller såsom led i en verksamhet som bedrivs vanemässigt eller annars i större omfattning, medverkar till en åtgärd som skäligen kan antas vara vidtagen i sådant syfte som anges i 3 §, döms för näringspenningtvätt till fängelse i högst två år. Är brottet grovt, döms till fängelse i lägst ett och högst sex år. Är brottet ringa, döms till böter eller fängelse i högst sex månader. Till samma straff döms den som i annat fall än som anges i första stycket medverkar till en åtgärd som skäligen kan antas vara vidtagen i sådant syfte som anges i 3 §. Lag (2026:1323) ."},"Brott mot tillståndsplikten för brandfarliga varor":{"ref":"LBE 29","text":"29 § Den som av oaktsamhet bryter mot 16 § första stycket döms till böter. Den som uppsåtligen eller av grov oaktsamhet bryter mot 16 § första stycket döms till 1. böter eller fängelse i högst ett år om brottet avser brandfarliga varor, eller 2. böter eller fängelse i högst fem år om brottet avser explosiva varor. Lag (2023:874) ."},"Brott mot tillståndsplikten för explosiva varor":{"ref":"LBE 29","text":"29 § Den som av oaktsamhet bryter mot 16 § första stycket döms till böter. Den som uppsåtligen eller av grov oaktsamhet bryter mot 16 § första stycket döms till 1. böter eller fängelse i högst ett år om brottet avser brandfarliga varor, eller 2. böter eller fängelse i högst fem år om brottet avser explosiva varor. Lag (2023:874) ."},"Grovt brott mot tillståndsplikten för explosiva varor":{"ref":"LBE 29 a","text":"29 a § Om uppsåtligt brott mot 16 § första stycket avser explosiva varor och är att anse som grovt döms till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. varan med hänsyn till dess effekt, konstruktion eller utformning har varit av särskilt farlig beskaffenhet, 2. hanteringen, överföringen, importen eller exporten har avsett flera varor eller en stor mängd av en vara, 3. hanteringen eller överföringen har skett i en sådan miljö att varan typiskt sett kan befaras komma till brottslig användning, eller 4. gärningen annars har varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt döms till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om hanteringen, överföringen, importen eller exporten har avsett ett stort antal varor eller en särskilt stor mängd av en vara eller flera varor av särskilt farlig beskaffenhet eller en stor mängd av en vara av särskilt farlig beskaffenhet. Lag (2023:874) ."},"Synnerligen grovt brott mot tillståndsplikten för explosiva varor":{"ref":"LBE 29 a","text":"29 a § Om uppsåtligt brott mot 16 § första stycket avser explosiva varor och är att anse som grovt döms till fängelse i lägst fyra och högst sju år. Vid bedömningen av om brottet är grovt ska det särskilt beaktas om 1. varan med hänsyn till dess effekt, konstruktion eller utformning har varit av särskilt farlig beskaffenhet, 2. hanteringen, överföringen, importen eller exporten har avsett flera varor eller en stor mängd av en vara, 3. hanteringen eller överföringen har skett i en sådan miljö att varan typiskt sett kan befaras komma till brottslig användning, eller 4. gärningen annars har varit av särskilt farlig art. Om brottet är att anse som synnerligen grovt döms till fängelse i lägst sex och högst tio år. Vid bedömningen av om brottet är synnerligen grovt ska det särskilt beaktas om hanteringen, överföringen, importen eller exporten har avsett ett stort antal varor eller en särskilt stor mängd av en vara eller flera varor av särskilt farlig beskaffenhet eller en stor mängd av en vara av särskilt farlig beskaffenhet. Lag (2023:874) ."},"$faultRule":"2 § En gärning skall, om inte annat är särskilt föreskrivet, anses som brott endast då den begås uppsåtligen. Har gärningen begåtts under självförvållat rus eller var gärningsmannen på annat vis genom eget vållande tillfälligt från sina sinnens bruk, skall detta inte föranleda att gärningen inte anses som brott. Lag (1994:458) ."};
const checkCard=(r)=>{
 const c=D.crimes.find(x=>!x.stageType&&x.title===r.title),p=pins[r.title];
 return !!(c&&p&&c.shortRef===p.ref&&c.lawMode==='full'&&c.lawCompletenessVerified===true
  &&c.lawCompletenessSourceURL===laws[r.code]&&/^2026-10-(18|19|20)$/.test(c.lawCompletenessChecked||'')
  &&norm(c.law)===p.text);
};
const report={planned:rows.length*2,completed:0,byFamily:{},held:[],byOffence:[],fullLegalApprovals:0,caseSpecificDecisions:0};
const norm=s=>String(s||'').replace(/\s+/g,' ').trim();
// A direct whole-paragraph comparison is independent of the old import flag.
// BrB 1:2 was reread in the current official consolidation on 2026-10-20.
const defaultFault=norm(W['BrB:1:2']?.text)===pins.$faultRule;
const familyReady=Object.fromEntries(Object.keys(laws).map(code=>[code,rows.filter(r=>r.code===code).every(checkCard)]));
for(const r of rows){
 const c=D.crimes.find(x=>!x.stageType&&x.title===r.title),pin=pins[r.title];
 const ready=c&&pin&&defaultFault&&familyReady[r.code]&&c.lawMode==='full'&&c.lawCompletenessVerified===true
  &&c.lawCompletenessSourceURL===laws[r.code]&&/^2026-10-(18|19|20)$/.test(c.lawCompletenessChecked||'')
  &&norm(c.law)===pin.text&&c.shortRef===pin.ref&&c.rekvisit15&&!c.rekvisit15.legalReviewApproved
  &&!c.legalAudit15?.checkpoints?.objective&&!c.legalAudit15?.checkpoints?.subjective;
 if(!ready){report.held.push(r.title);continue;}
 const checkpoints={};for(const key of ['objective','subjective']){
  checkpoints[key]={status:'APPROVED',checked:'2026-10-20',sourceURL:laws[r.code],sourceRefs:r.refs,
   finding:r[key],scope:'current-special-law-statutory-elements-only',caseSpecificLiabilityApproved:false,
   caseSpecificCustodyApproved:false,historicLawApproved:false,jurisprudenceApproved:false,allCompetingOffencesReviewed:false};
  report.completed++;report.byFamily[r.code]=(report.byFamily[r.code]||0)+1;
 }
 c.legalAudit15={...(c.legalAudit15||{}),schema:1,sourceAudit:'special-elements-2026-10-20',
  checkpoints:{...(c.legalAudit15?.checkpoints||{}),...checkpoints},fullLegalReviewApproved:false};
 c.rekvisit15.explanations15=[{title:'Objektiva krav – förklaring',text:r.objective},{title:'Subjektiva krav – förklaring',text:r.subjective}];
 report.byOffence.push({title:r.title,code:r.code,checks:['objective','subjective']});
}
window.BK_SPECIAL_ELEMENTS_AUDIT15=report;
})();
